L["0 follows the font size on the Look tab."] = "При 0 используется размер шрифта со вкладки «Вид»."
L["0 hides it (the default): it shows only while the buff is missing."] = "0 скрывает его (по умолчанию): он показывается, только пока эффект отсутствует."
L["0 hides it while the hand has no weapon to enchant."] = "0 скрывает, пока в руке нет оружия для чар."
L["0 hides it."] = "0 скрывает."
L["0 hides it; the rules under the table can bring it back."] = "0 скрывает; правила под таблицей могут вернуть."
L["0 hides the bar between casts."] = "0 скрывает полосу между применениями."
L["0 hugs the entries. More keeps the window at least that tall."] = "0 - по размеру записей. Большее значение задает минимальную высоту окна."
L["0 is normal. A higher priority wins the screen spot and is the last out of a full queue. Ties follow Overlap Behavior."] = "0 - обычный. Более высокий приоритет занимает место на экране и последним покидает полную очередь. При равенстве действует «Поведение наложения»."
L["0 keeps a ping until newer ones push it out."] = "При 0 пинг остается, пока его не вытеснят новые."
L["1 bar"] = "1 полоса"
L["1 group"] = "1 группа"
L["1 icon"] = "1 значок"
L["1 icon in it is set to not displayed in your Cooldown Manager, so it stays out."] = "1 значок в нем не отображается в вашем Трекере восстановления, поэтому не импортируется."
L["1 kind"] = "1 вид"
L["1 layout hidden here. Show it"] = "Здесь скрыт 1 макет. Показать его"
L["1 match"] = "1 совпадение"
L["1 of them is in Arc Auras already: importing again adds a second copy."] = "1 из них уже есть в Arc Auras: повторный импорт добавит вторую копию."
L["1 profile"] = "1 профиль"
L["1 reminder"] = "1 напоминание"
L["1 rule"] = "1 правило"
L["1 setting differs from the group; a cyan bar marks it."] = "1 отличие от группы; оно отмечено голубой полосой."
L["1 texture"] = "1 текстура"
L["3 to 10, spot 1 at the top. Fewer spots keep what sat on the others: it comes back with more."] = "От 3 до 10, место 1 вверху. При меньшем числе мест то, что стояло на остальных, сохраняется и возвращается, когда мест станет больше."
L["30 is a debuff's pandemic window. Needs no length."] = "30 - окно пандемии отрицательного эффекта. Длина не нужна."
L[": matches again ("] = ": matches again ("
L["A 2.6 second timer that runs out and starts again."] = "Таймер на 2,6 секунды: истекает и запускается снова."
L["A Cooldown Manager icon"] = "Значок Трекера восстановления"
L["A Custom Icon or Bar"] = "Свой значок или полоса"
L["A Custom Icon or Bar's value"] = "Значение своего значка или полосы"
L["A Dynamic aura group only tracks you, your pet and your target."] = "Динамическая группа отслеживает только вас, питомца и цель."
L["A Dynamic group only tracks you, your pet and your target: turn its Dynamic off."] = "Динамическая группа отслеживает только вас, питомца и цель: выключите ее параметр «Динамика»."
L["A blank layout. Add your own groups, icons and bars."] = "Пустой макет. Добавьте свои группы, значки и полосы."
L["A buff or debuff as an icon; several IDs can light one icon."] = "Положительный или отрицательный эффект в виде значка; один значок могут зажигать несколько ID."
L["A cast that finishes, one that is interrupted, then a channel."] = "Применение завершается, затем прерывается, затем направляемое заклинание."
L["A cast while it runs: start it over, add the seconds to what is left, leave it running, or end it."] = "Применение, пока таймер идет: начать заново, добавить секунды к остатку, оставить как есть или завершить."
L["A charge left and another coming back, over and over: the Recharging look, with its opacity, grey out, tint and glow."] = "Заряд остается, а другой возвращается, снова и снова: вид «Перезарядка» с его непрозрачностью, обесцвечиванием, оттенком и свечением."
L["A condition holds"] = "Условие выполняется"
L["A condition turns off"] = "Условие выключается"
L["A condition turns on"] = "Условие включается"
L["A cooldown ID names a Cooldown Manager icon, so it stays at its own spot."] = "ID восстановления указывает на значок Трекера восстановления, поэтому он остается на своем месте."
L["A cooldown ID names a Cooldown Manager icon."] = "ID восстановления указывает на значок Трекера восстановления."
L["A deck bar fills as the deck is drawn, with a mark for each proc."] = "Полоса колоды заполняется по мере розыгрыша колоды, с меткой для каждого прока."
L["A deck of 100 stacks holding 2 Tempest procs."] = "Колода из 100 стаков с 2 проками «Буря»."
L["A deck of 250 stacks holding 5 Storm Unleashed procs."] = "Колода из 250 стаков с 5 проками «Необузданная буря»."
L["A deck of 333 Maelstrom holding 2 Tempest procs."] = "Колода из 333 Энергии Водоворота с 2 проками «Буря»."
L["A deck of 333 stacks holding 2 Ascendance procs."] = "Колода из 333 стаков с 2 проками «Перерождение»."
L["A deck of 600 Maelstrom Weapon stacks holding 3 Doom Winds procs."] = "Колода из 600 стаков «Оружие Водоворота» с 3 проками «Ветра рока»."
L["A dim dark line along the edge, under the moving lines."] = "Тусклая темная линия по краю, под движущимися линиями."
L["A divider where each stage of an empowered cast begins, in the tick look. Shows with tick marks off too."] = "Разделитель там, где начинается каждый этап усиления, в виде метки. Виден и при выключенных метках."
L["A female voice"] = "Женский голос"
L["A fill, like a bar"] = "Заполнение, как у полосы"
L["A glow around the bar, with a trigger of its own. Works in combat."] = "Свечение вокруг полосы со своим триггером. Работает в бою."
L["A grid of small tiles showing the art and the name. Click a tile to edit it. Hover it for its details, Edit and Delete."] = "Сетка маленьких плиток с рисунком и названием. Щелкните плитку, чтобы изменить. Наведите курсор: сведения, «Изменить» и «Удалить»."
L["A group needs at least one column."] = "В группе должен быть хотя бы один столбец."
L["A group needs at least one row."] = "В группе должен быть хотя бы один ряд."
L["A layout for 1 class"] = "Макет для 1 класса"
L["A layout pack you use has a newer version."] = "У используемого вами набора макетов есть новая версия."
L["A longer line widens the window for as long as it shows."] = "Более длинная строка расширяет окно, пока она показана."
L["A look of its own under a time left"] = "Свой вид, когда осталось меньше заданного времени"
L["A look under a time left"] = "Вид при остатке времени меньше заданного"
L["A male voice"] = "Мужской голос"
L["A mark where each spell's cost is met. It shows with Tick marks on (Appearance > Ticks)."] = "Метка там, где хватает затрат на каждое заклинание. Показывается при включенных «Метках» (Внешний вид > Метки)."
L["A mark where your next spell can be queued: press it past the mark and it goes off as soon as this cast ends."] = "Метка, с которой можно поставить в очередь следующее заклинание: нажмите после нее, и оно сработает сразу после этого применения."
L["A missing aura"] = "Отсутствующая аура"
L["A name, version, link and notes for your pack. Whoever imports the string sees them first."] = "Название, версия, ссылка и заметки для вашего набора. Тот, кто импортирует строку, увидит их первыми."
L["A named frame"] = "Именованный фрейм"
L["A nameplate: not offered"] = "Индикатор здоровья: не предлагается"
L["A new rule: when something happens, what it does."] = "Новое правило: когда что-то происходит, что оно делает."
L["A newer version is out: click to update your copy"] = "Вышла новая версия: щелкните, чтобы обновить свою копию"
L["A newer version of this layout is out. Updates the layout you made from it; your own sizes and positions stay."] = "Вышла новая версия этого макета. Обновляет созданный из него макет; ваши размеры и позиции сохраняются."
L["A percent of the bar, or power with In power units on."] = "Процент от полосы или значение ресурса при включенном «В единицах ресурса»."
L["A picture of your own: its FileDataID, or its path such as Interface/AddOns/MyMedia/glow. Enter applies it; empty = pick one above."] = "Своя картинка: ее FileDataID или путь, например Interface/AddOns/MyMedia/glow. Enter применяет; пусто = выбрать выше."
L["A picture that follows an aura, a cooldown, your power, health or triggers."] = "Картинка, которая следует за аурой, восстановлением, вашим ресурсом, здоровьем или триггерами."
L["A power bar; Automatic follows the power you are using."] = "Полоса ресурса; «Авто» следует за используемым ресурсом."
L["A proc glow ended"] = "Свечение прока закончилось"
L["A proc glow started"] = "Свечение прока началось"
L["A proc shows it at full opacity"] = "Прок показывает это с полной непрозрачностью"
L["A quarter turn: the bar becomes tall and thin, and its icon, texture and gradient turn with it."] = "Поворот на 90°: полоса становится высокой и узкой, а значок, текстура и градиент поворачиваются вместе с ней."
L["A reactive ability lit up"] = "Загорелась реактивная способность"
L["A reminder exported on its own joins this group. A group keeps one reminder per spell, item or weapon hand, so duplicates stay out."] = "Напоминание, экспортированное отдельно, присоединяется к этой группе. Группа хранит одно напоминание на заклинание, предмет или руку с оружием, поэтому дубликатов не будет."
L["A returning icon"] = "Возвращающийся значок"
L["A ring of your spells and items: hold its key, point at one and let go to cast it."] = "Кольцо из ваших заклинаний и предметов: удерживайте его клавишу, наведите на нужное и отпустите, чтобы применить."
L["A ring, like a cooldown"] = "Кольцо, как у восстановления"
L["A set duration"] = "Заданная длительность"
L["A share of the time"] = "Доля времени"
L["A short flash"] = "Короткая вспышка"
L["A short word, like %s"] = "Короткое слово, например %s"
L["A short word, like C"] = "Короткое слово, например C"
L["A short word, like D"] = "Короткое слово, например D"
L["A short word, like M"] = "Короткое слово, например M"
L["A short word, like N"] = "Короткое слово, например N"
L["A short word, like P"] = "Короткое слово, например P"
L["A skin made from the default look. A bar's Skin dropdown makes one from that bar's look."] = "Скин из вида по умолчанию. Список «Скин» у полосы создает скин из вида этой полосы."
L["A soft glow around the icon in this type's color. Glow size is under All."] = "Мягкое свечение вокруг значка цветом этого типа. Размер свечения - в разделе «Все»."
L["A sound"] = "Звук"
L["A spare profile in Arc UI: its groups and icons come in switched off; turn them on in their Load tab."] = "Запасной профиль в Arc UI: его группы и значки приходят выключенными; включите их в условиях загрузки."
L["A spark crosses the bar every 2 seconds and lands on each mana tick."] = "Искра пересекает полосу каждые 2 секунды и останавливается на каждом тике маны."
L["A spell"] = "Заклинание"
L["A spell ID, a link, or the name of a spell you know."] = "ID заклинания, ссылка или название известного вам заклинания."
L["A spell ID, a link, or the name of a spell you know. Any rank of it counts unless Only this rank is on."] = "ID заклинания, ссылка или название известного вам заклинания. Считается любой его ранг, если не включено «Только этот ранг»."
L["A spell ID, a link, or the name of a spell you know. Enter applies it."] = "ID заклинания, ссылка или название известного вам заклинания. Enter применяет."
L["A spell ID, a spell link, or the name of a spell in your spellbook: for spells the catalog does not list."] = "ID заклинания, ссылка на заклинание или название заклинания из вашей книги заклинаний: для заклинаний, которых нет в каталоге."
L["A spell ID, or the name of a spell you know. Any rank works: the bar follows the rank you know."] = "ID заклинания или название известного вам заклинания. Подходит любой ранг: полоса следует за известным вам рангом."
L["A spell ID, or the name of a spell you know. It goes on the first empty spot; one you have not learned yet shows grey until you do."] = "ID заклинания или название известного вам заклинания. Оно занимает первое пустое место; неизученное заклинание отображается серым, пока вы его не изучите."
L["A spell ID, or the name of a spell you know. The rank you know is checked."] = "ID заклинания или название известного вам заклинания. Проверяется известный вам ранг."
L["A spell became usable"] = "Заклинание стало доступным"
L["A spell is on cooldown"] = "Заклинание на восстановлении"
L["A spell is ready"] = "Заклинание готово"
L["A spell is recharging"] = "Заклинание перезаряжается"
L["A spell is usable"] = "Заклинание доступно"
L["A spell name or ID, such as Raptor Strike, Heroic Strike or Maul. Its marker shows where it comes off cooldown and while it is queued."] = "Название или ID заклинания, например «Удар ящера», «Удар героя» или «Трепка». Его метка показывает, где закончится восстановление, и пока он в очереди."
L["A spell stopped being usable"] = "Заклинание стало недоступным"
L["A spell's charges"] = "Заряды заклинания"
L["A spell's cooldown"] = "Восстановление заклинания"
L["A spell's cooldown as an icon."] = "Восстановление заклинания в виде значка."
L["A spell's cooldown ended"] = "Восстановление заклинания закончилось"
L["A spell's cooldown started"] = "Восстановление заклинания началось"
L["A spell's custom text"] = "Свой текст заклинания"
L["A spend every half second, a proc at a third and two thirds of the deck, then a new deck."] = "Трата каждые полсекунды, прок на трети и двух третях колоды, затем новая колода."
L["A spot mid-screen where your cooldowns pulse as they come back."] = "Место в середине экрана, где пульсируют ваши восстановления, когда они возвращаются."
L["A stance, form or aura from your stance bar. The icon lights up while you are in it."] = "Стойка, облик или аура с вашей панели стоек. Значок загорается, пока вы в ней."
L["A string to share this skin."] = "Строка, чтобы поделиться этим скином."
L["A swipe over each icon while it is on cooldown."] = "Затемнение поверх каждого значка, пока он на восстановлении."
L["A tick where each proc of this deck landed. A new deck clears them."] = "Метка там, где сработал каждый прок этой колоды. Новая колода очищает метки."
L["A totem is gone"] = "Тотем исчез"
L["A totem or guardian in its slot, or one of them by the spell that puts it down."] = "Тотем или страж в своей ячейке либо один из них по заклинанию, которое его ставит."
L["A totem slot"] = "Ячейка тотема"
L["A totem was placed"] = "Тотем поставлен"
L["A totem with 14 of its 24 seconds left, standing still."] = "Тотем, у которого осталось 14 из 24 секунд, неподвижно."
L["A trinket or other gear reminds you only while you wear it."] = "Аксессуар или другая экипировка напоминает о себе, только пока вы ее носите."
L["A unit's health, with incoming heals and shields."] = "Здоровье юнита с входящим лечением и щитами."
