L["Anyone: any copy counts. Me: only yours, so your Beacon or Earth Shield, not another player's."] = "Любой: учитывается любая копия. Я: только ваша, то есть ваши «Частица Света» или «Щит земли», а не чужие."
L["Anyone: any copy fills the bar. Me: only yours or your pet's. Anyone but me: only copies from other players."] = "Кто угодно: полосу заполняет любая копия. Я: только ваша или вашего питомца. Кто угодно, кроме меня: только копии других игроков."
L["Anyone: any copy lights the icon. Me: only yours or your pet's. Anyone but me: only copies from other players."] = "Кто угодно: значок зажигает любая копия. Я: только ваша или вашего питомца. Кто угодно, кроме меня: только копии других игроков."
