L["Copies one of your macros into the box below as a start. It never takes that macro over."] = "Копирует один из ваших макросов в поле ниже как заготовку. Сам макрос не перехватывается."
L["Copies the layout's class and talent checks to those items so they load where the layout does. Load When rules stay."] = "Копирует проверки класса и талантов макета в эти элементы, чтобы они загружались там же, где макет. Правила «Загружать, когда» остаются."
