L["Copies the rows of this sub-panel onto the chosen target. Copy semantics - no live link; the target keeps its own values from then on."] = "Копирует строки этой подпанели в выбранную цель. Это копия, а не связь: дальше у цели свои значения."
L["Copies the selection to the picked place and leaves the originals. Each copy keeps its settings, name and position."] = "Копирует выбранное в указанное место, оставляя оригиналы. Каждая копия сохраняет свои настройки, название и позицию."
L["Copies this group's class and spec checks onto those icons, so they load wherever the group does."] = "Копирует проверки класса и специализации этой группы на эти значки, и они загружаются везде, где загружается группа."
