L["Drag a spell from the list, your spellbook, your bags or your bars onto a spot. Right-click a spot to empty it."] = "Перетащите заклинание из списка, книги заклинаний, сумок или панелей на место. Щелкните место правой кнопкой, чтобы очистить его."
L["Drag an element to move it, its handles to size it; the outline moves all, corners scale, the cross sets the center. Alt drags free."] = "Перетащите элемент, чтобы переместить его, а его маркеры - чтобы изменить размер; контур перемещает все, углы меняют масштаб, крест задает центр. Alt - свободное перетаскивание."
L["Drag any of them to move them together. Arrows nudge them all."] = "Перетащите любой из них, чтобы переместить все вместе. Стрелки сдвигают все."
L["Drag it onto a spot, or click to add it."] = "Перетащите на место или щелкните, чтобы добавить."
L["Drag it to move it. Right-click to take it off."] = "Перетащите, чтобы переместить. Щелкните правой кнопкой, чтобы убрать."
L["Drag on screen"] = "Перетаскивать на экране"
L["Drag the layout anywhere on your screen."] = "Перетащите макет в любое место на экране."
