L["Drops every talent picked in this tree. Other classes' and specs' picks stay."] = "Сбрасывает все таланты, выбранные в этом дереве. Выбор других классов и специализаций сохраняется."
L["Drops every talent picked in this tree. Other classes' picks stay."] = "Сбрасывает все таланты, выбранные в этом дереве. Выбор других классов сохраняется."
L["Drops the own values items of this kind hold for the rows on this page, so they follow your defaults. It asks first and says how many."] = "Сбрасывает собственные значения строк этой страницы у элементов этого вида, и они следуют вашим значениям по умолчанию. Сначала спросит и скажет, сколько их."
L["Drops this icon's own looks, so it takes the ones its defaults set."] = "Сбрасывает собственные виды этого значка, и он берет те, что заданы его значениями по умолчанию."
L["Drops this icon's own looks, so it takes the ones its layout sets."] = "Сбрасывает собственные виды этого значка, и он берет те, что заданы его макетом."
L["Drops this reminder's own appearance settings, so every one of them follows the group again."] = "Сбрасывает собственные настройки внешнего вида этого напоминания, и все они снова следуют группе."
L["Drops your saved default for these rows, so they read Arc's again. It asks whether the items you have change too."] = "Сбрасывает ваше сохраненное значение по умолчанию для этих строк, и они снова берут значения Arc. Спросит, менять ли и имеющиеся у вас элементы."
