L["Each icon group, and your free icons, gets a skin you pick in Masque's options: picture size and crop, border, backdrop and gloss."] = "Каждая группа значков и ваши свободные значки получают скин, который вы выбираете в параметрах Masque: размер и обрезка картинки, рамка, фон и блеск."
L["Each icon shows only while its buff is missing, in combat too."] = "Каждый значок показывается, только пока его эффекта нет, в том числе в бою."
L["Each icon's Text > Custom Text & Keybind sets the text's size, color and position."] = "Размер, цвет и положение текста задаются в разделе «Текст» > «Свой текст и клавиша» каждого значка."
L["Each number in the custom list wears its own colour, in the order you typed them; the Tick color is the first."] = "Каждое число в своем списке получает свой цвет в том порядке, в котором вы их ввели; первый - «Цвет метки»."
L["Each power (druid forms)"] = "Каждый ресурс (облики друида)"
