L["Emity's Discord"] = "Discord Emity"
L["Emity's latest version: Dark Inspiration, anchors for more player frames, and stack counts from 1."] = "Последняя версия Emity: Dark Inspiration, привязки к большему числу рамок игрока и счётчик стаков с 1."
L["Emity's latest version: Incinerate, Conflagrate and Soul Fire, Demon Skin in Missing Buffs, anchors for more player frames, and stack counts from 1."] = "Последняя версия Emity: Испепеление, Поджигание и Ожог души, Демоническая кожа среди недостающих баффов, привязки к большему числу рамок игрока и счётчик стаков с 1."
L["Emity's latest version: Maelstrom Weapon and mana bars for Enhancement, Elemental Mastery, anchors for more player frames, and stack counts from 1."] = "Последняя версия Emity: полосы Оружия водоворота и маны для Совершенствования, Покорение стихий, привязки к большему числу рамок игрока и счётчик стаков с 1."
L["Emity's latest version: Reckoning, the new Vindication, Blessing of Freedom, anchors for more player frames, and stack counts from 1."] = "Последняя версия Emity: Расплата, новое Возмездие, Благословение свободы, привязки к большему числу рамок игрока и счётчик стаков с 1."
L["Emity's latest version: Revenge and Overpower icons that light up when you can use them."] = "Последняя версия Emity: значки Реванша и Превосходства, которые загораются, когда их можно применить."
L["Emity's latest version: Scorpid Sting, Scatter Shot and Expose Prey on your target, both hawks, your off-hand enchant, anchors for more player frames, and stack counts from 1."] = "Последняя версия Emity: Укус скорпида, Дезориентирующий выстрел и Expose Prey на цели, оба ястреба, чары левой руки, привязки к большему числу рамок игрока и счётчик стаков с 1."
L["Emity's latest version: a Thousand Cuts bar for Subtlety, anchors for more player frames, and stack counts from 1."] = "Последняя версия Emity: полоса Thousand Cuts для Скрытности, привязки к большему числу рамок игрока и счётчик стаков с 1."
L["Emity's latest version: bars for Arcane Blast, Heating Up and Fingers of Frost, Arcane Wrath, anchors for more player frames, and stack counts from 1."] = "Последняя версия Emity: полосы Чародейской вспышки, Разогрева и Ледяных пальцев, Arcane Wrath, привязки к большему числу рамок игрока и счётчик стаков с 1."
L["Emity's latest version: missing buff reminders show only for spells you know."] = "Последняя версия Emity: напоминания об отсутствующих баффах показываются только для известных вам заклинаний."
