L["Every icon in the group as the game's Cooldown Manager draws it: rounded corners, border, shadow and swipe."] = "Каждый значок группы выглядит, как в Трекере восстановления игры: скругленные углы, рамка, тень и затемнение."
L["Every icon in this layout uses these looks unless it sets its own."] = "Каждый значок этого макета использует эти виды, если не задан свой."
L["Every item of this kind: the icon follows the one you last used, as the Cooldown Manager's does."] = "Каждый предмет этого вида: значок следует за последним использованным, как в Трекере восстановления."
L["Every other kind"] = "Все остальные виды"
L["Every other kind of %s (%d)"] = "Все остальные виды: %s (%d)"
L["Every piece back where it ships, both shown, the default spacing. Asks for a second click."] = "Все элементы возвращаются на свои места по умолчанию, оба показаны, отступы по умолчанию. Нужен второй щелчок."
L["Every point"] = "Каждая точка"
L["Every press"] = "Каждое нажатие"
L["Every rank counts, from anyone."] = "Считается любой ранг, от кого угодно."
L["Every rank of the buff, and its group version, separated by commas or spaces. A member counts as having it with any of them on."] = "Каждый ранг положительного эффекта и его групповая версия через запятую или пробел. Участник считается имеющим эффект, если действует любой из них."
L["Every row on this page back to Arc's value. It asks whether the items you have change too."] = "Все строки этой страницы возвращаются к значениям Arc. Спросит, менять ли и имеющиеся у вас элементы."
L["Every stack added runs its own timer (the rule's seconds, else Default seconds) and drops off when it ends."] = "Каждый добавленный стак запускает свой таймер (секунды правила, иначе «Секунды по умолчанию») и пропадает по его окончании."
L["Every texture and font it uses is on this PC."] = "Все используемые им текстуры и шрифты есть на этом компьютере."
L["Every time I press its key"] = "Каждый раз при нажатии его клавиши"
