L["Hide while editing"] = "Скрывать при правке"
L["Hides between casts; shows a sample cast while this window is open."] = "Скрывается между применениями; пока это окно открыто, показывает пример применения."
L["Hides casts you cannot interrupt. In combat the game hides that from addons, so it cannot drive sounds or alerts."] = "Скрывает применения, которые нельзя прервать. В бою игра скрывает это от аддонов, поэтому запускать по этому признаку звуки и сигналы нельзя."
L["Hides it on screen while this window is open, so you can get at what sits under it. Closing the window shows it again."] = "Скрывает его на экране, пока окно открыто, чтобы можно было добраться до того, что под ним. Когда окно закроется, он снова появится."
L["Hides the game's castbar under your character while this castbar is loaded. Turn off to bring it back on your next cast."] = "Скрывает стандартный индикатор заклинаний под вашим персонажем, пока загружен этот индикатор. Выключите, и он вернется при следующем применении."
L["Hides the minimap button. %s always opens this window. Drag the button along the rim to move it, right-click for move mode."] = "Скрывает кнопку на миникарте. %s всегда открывает это окно. Перетащите кнопку вдоль края, чтобы переместить ее; щелчок правой кнопкой - режим перемещения."
L["Hides this update here until the next version. The tag on the layout in the sidebar stays."] = "Скрывает это обновление здесь до следующей версии. Метка на макете в боковой панели остается."
L["Hides while the unit is not there; always shows while this window is open."] = "Скрывается, пока юнита нет; пока это окно открыто, показывается всегда."
L["High"] = "Высокий"
L["High threat"] = "Высокая угроза"
L["Highest rank"] = "Высший ранг"
L["Highlight color"] = "Цвет подсветки"
L["Highlight icons when you press their button"] = "Подсвечивать значки при нажатии их кнопки"
L["Highlight lasts"] = "Подсветка длится"
L["Highlight opacity"] = "Непрозрачность подсветки"
L["Hold %s over any bound spell to ping it."] = "Удерживайте %s и нажмите клавишу назначенного заклинания, чтобы отправить его пинг."
L["Hold %s over any bound spell to ping it. %d of %d picked spells ping their own way."] = "Удерживайте %s и нажмите клавишу назначенного заклинания, чтобы отправить его пинг. Пингуют по-своему: %d из %d выбранных заклинаний."
L["Hold %s, then press %s."] = "Удерживайте %s, затем нажмите %s."
L["Hold for (s)"] = "Удерживать (с)"
L["Hold interrupted and failed casts"] = "Удерживать прерванные и неудавшиеся применения"
L["Hold the ping key and press a spell's own key to ping it instead of casting it. Nothing is rebound while this is off."] = "Удерживайте клавишу пинга и нажмите клавишу заклинания, чтобы отправить пинг вместо применения. Пока выключено, ничто не переназначается."
L["Hold this and press a spell's key to ping the spell. Click, then press a key; right-click clears it."] = "Удерживайте эту клавишу и нажмите клавишу заклинания, чтобы отправить его пинг. Щелкните, затем нажмите клавишу; правый щелчок очищает."
L["Hold this instead of the main ping key to ping this spell. Not set uses the main ping key. Right-click clears it."] = "Удерживайте эту клавишу вместо основной клавиши пинга, чтобы отправить пинг этого заклинания. Если не задана, используется основная клавиша пинга. Правый щелчок очищает."
L["Hold: its key still casts, and holding the ping key pings instead. Every press: casts and pings. Its own key: pings and casts nothing."] = "Удержание: его клавиша по-прежнему применяет заклинание, а удержание клавиши пинга пингует. Каждое нажатие: применяет и пингует. Своя клавиша: только пингует, заклинание не применяется."
L["Holds"] = "Удерживает"
L["Holds %s."] = "Удерживает: %s."
L["Holds on every power."] = "Выполняется для любого ресурса."
L["Holds only while the bar shows %s."] = "Удерживает, только пока полоса показывает: %s."
L["Holds the proc glow lit on a ready icon."] = "Удерживает свечение прока на готовом значке."
L["Holds the ready glow lit."] = "Удерживает свечение готовности."
L["Holds while the aura is up at this many stacks. Its effects apply only then."] = "Выполняется, пока аура активна с таким числом стаков. Эффекты применяются только тогда."
L["Holds while the spell has this many charges. Its effects apply only then; in a Dynamic group it keeps its place."] = "Выполняется, пока у заклинания столько зарядов. Эффекты применяются только тогда; в динамической группе значок остаётся на своём месте."
L["Holds:"] = "Удерживает:"
L["Holy Power"] = "Энергия Света"
L["Home"] = "Главная"
L["Horizontal"] = "Горизонтально"
L["Horizontal packs each row sideways; Vertical packs each column up or down."] = "«Горизонтально» упаковывает каждый ряд вбок; «Вертикально» упаковывает каждый столбец вверх или вниз."
L["Hot chance color"] = "Цвет высокого шанса"
L["Hot from (%)"] = "Высокий шанс от (%)"
L["Hover a game frame on screen and click it. Right-click or Esc cancels."] = "Наведите курсор на фрейм игры на экране и щелкните. Правая кнопка или Esc отменяют."
L["Hover a game frame or one of your Arc Auras items and click it. On an icon in a group, Shift-click takes the icon."] = "Наведите на фрейм игры или элемент Arc Auras и щёлкните. На значке в группе Shift+щелчок выбирает сам значок."
L["Hover a game frame, an action button, a Cooldown Manager icon or an Arc Auras icon and left-click it. Right-click or Esc cancels."] = "Наведите курсор на фрейм игры, кнопку панели команд, значок Трекера восстановления или значок Arc Auras и щелкните левой кнопкой. Правая кнопка или Esc отменяют."
L["Hovering an icon shows its spell, item or totem tooltip."] = "При наведении на значок показывается подсказка его заклинания, предмета или тотема."
L["How big the preview is against the bar's real size. Click to fit the whole bar in view again."] = "Размер просмотра относительно реального размера полосы. Щелкните, чтобы снова уместить всю полосу."
L["How countdown numbers round. Up: 13.2 reads 14, like action bar cooldowns. Down: 13.2 reads 13, like buff timers and nameplates."] = "Как округляются числа отсчета. Вверх: 13,2 читается как 14, как у восстановления на панелях команд. Вниз: 13,2 читается как 13, как у таймеров эффектов и индикаторов здоровья."
L["How far the glow reaches past the icon: 1 sits on its edge."] = "Насколько свечение выходит за значок: 1 - на самом краю."
L["How far your target is, in colored range bands you can edit."] = "Как далеко ваша цель, в цветных диапазонах дальности, которые можно изменять."
L["How fast a line is spoken. 0 follows WoW's own speech rate."] = "С какой скоростью произносится строка. 0 - скорость речи самой WoW."
L["How it looks in each state"] = "Вид в каждом состоянии"
L["How it shows"] = "Как показывается"
L["How long a flash shows. A held button keeps the highlight at least this long, so clicks that cast on release still show."] = "Как долго показывается вспышка. Удерживаемая кнопка сохраняет подсветку не меньше этого времени, поэтому щелчки, применяющие при отпускании, тоже видны."
L["How long after that rule last fired this one may fire (Not after: may not fire). Enter applies it."] = "Сколько времени после последнего срабатывания того правила это правило может срабатывать («Не после»: не может срабатывать). Enter применяет."
L["How long after your cast it may land and still light this in combat. One that flies in first needs longer (Summon Hawk: 1.5 s)."] = "Сколько после применения он может появиться и все еще зажечь это в бою. Тому, кто сначала летит, нужно больше (Summon Hawk: 1.5 с)."
L["How long it shows after each cast."] = "Сколько показывается после каждого применения."
L["How long the bar takes to fade away when a cast ends (after the hold, when that is on). 0 = it goes at once."] = "Сколько полоса исчезает после окончания применения (после удержания, если оно включено). 0 = сразу."
L["How long the button glow takes to fade when it stops. 0: it goes at once."] = "Сколько затухает свечение кнопки после остановки. 0: сразу."
L["How long the timer runs when a rule starts it with no seconds of its own. Enter applies it."] = "Сколько идет таймер, когда правило запускает его без собственных секунд. Enter применяет."
L["How long the timer runs, and each stack when stacks run out on their own, when a rule gives no seconds. Enter applies it."] = "Сколько идет таймер и каждый стак, когда стаки заканчиваются сами, если правило не задает секунды. Enter применяет."
L["How long the timer runs, or an added stack lasts; 0 takes the item's Default seconds. Decimals work (1.5). Enter applies it."] = "Сколько идет таймер или длится добавленный стак; 0 берет секунды по умолчанию у предмета. Допустимы десятичные (1.5). Enter применяет."
L["How long, in seconds; decimals work (1.5). Enter applies it."] = "Сколько, в секундах; допустимы десятичные (1.5). Enter применяет."
L["How many"] = "Сколько"
L["How many charges are up; Blank at zero below hides the 0."] = "Сколько зарядов есть; «Пусто при нуле» ниже скрывает 0."
L["How many in your party or raid have a buff."] = "Сколько в вашей группе или рейде имеют положительный эффект."
L["How many nameplates get a row, in the order the game numbers them. Each one keeps a set of frames ready."] = "Для скольких индикаторов здоровья создается ряд, в порядке нумерации игры. Для каждого наготове набор фреймов."
L["How many rows of auras show, each Columns wide; up to 40 auras. The rest show as others end."] = "Сколько рядов аур показывается, каждый шириной «Столбцы»; до 40 аур. Остальные появляются по мере окончания других."
L["How many stacks the next spender eats; the chance is for that many draws."] = "Сколько стаков съест следующая трата; шанс считается на столько розыгрышей."
L["How many stage colors to list and show while editing; set it to your spell's stages."] = "Сколько цветов этапов показывать в списке и при редактировании; укажите число этапов заклинания."
L["How many you carry, on items that stack, such as potions."] = "Сколько у вас с собой - для стопкующихся предметов, например зелий."
L["How the bar looks in each state"] = "Вид полосы в каждом состоянии"
L["How visible the icon is %s."] = "Насколько виден значок %s."
L["How visible the icon is on cooldown until On cooldown's opacity starts."] = "Насколько виден значок на восстановлении, пока не начнется непрозрачность «На восстановлении»."
L["How visible the icon is until this opacity starts. 0 hides it."] = "Насколько виден значок, пока не начнется эта непрозрачность. 0 скрывает его."
L["How visible the icon is while the aura is up, until Active's opacity starts."] = "Насколько виден значок, пока аура действует, пока не начнется непрозрачность «Активно»."
L["How visible the icon is while this look shows. 0 hides it."] = "Насколько виден значок, пока показан этот вид. 0 скрывает его."
L["However many pings arrive, the sound plays at most once in this time."] = "Сколько бы пингов ни пришло, звук играет не чаще одного раза за это время."
