L["It can't be dragged on screen."] = "Его нельзя перетаскивать на экране."
L["It fires once the enchant has this many charges or fewer left. Enter applies it."] = "Срабатывает, когда у чар остается столько зарядов или меньше. Enter применяет."
L["It glows while this look shows, in its state's glow colour."] = "Светится, пока показан этот вид, цветом свечения своего состояния."
L["It has no key on your bars: bind one, or give it its own key."] = "У него нет клавиши на ваших панелях: назначьте ее или задайте ему свою клавишу."
L["It has stacks"] = "Есть стаки"
L["It keeps its spot in its Dynamic group."] = "Сохраняет свое место в динамической группе."
L["It lasts (seconds)"] = "Длится (секунды)"
L["It pulses when its cooldown is back; add more triggers after."] = "Пульсирует, когда его восстановление закончилось; позже можно добавить другие триггеры."
L["It pulses when the enchant is missing; add more triggers after."] = "Пульсирует, когда чар нет; позже можно добавить другие триггеры."
L["It shows beside the pulse while the aura is missing, in combat too."] = "Показывается рядом с пульсацией, пока ауры нет, в том числе в бою."
L["It sits by the group and moves with it."] = "Находится рядом с группой и перемещается вместе с ней."
L["It sits on the first one that is on screen, top to bottom."] = "Привязывается к первому из тех, что на экране, сверху вниз."
L["It starts as this state's look. When several hold, the top one wins."] = "Начинается с вида этого состояния. Если подходит несколько, побеждает верхний."
L["It starts out of combat, or after a /reload."] = "Запускается вне боя или после /reload."
L["It wears the spell whose cast started its timer: one Fire Trap icon for whichever fire trap you laid."] = "Показывает заклинание, чье применение запустило его таймер: один значок «Огненной ловушки» для любой поставленной огненной ловушки."
