L["Items that came from this pack but are no longer in the string go. Anything you added yourself always stays."] = "Элементы, пришедшие из этого набора, которых больше нет в строке, удаляются. Все, что вы добавили сами, остается всегда."
L["Items you deleted"] = "Удаленные вами элементы"
