L["Its bars become a new layout of groups: same spells, sizes and places. Then it turns off."] = "Его полосы становятся новым макетом из групп: те же заклинания, размеры и места. Затем он выключается."
L["Its buff"] = "Его эффект"
L["Its group orders by Time left, so in play it wears a new aura icon's look."] = "Его группа упорядочена по «Оставшемуся времени», поэтому в игре он выглядит как новый значок ауры."
L["Its group turns this look on: the group's Appearance > Icons."] = "Этот вид включает его группа: «Внешний вид» > «Значки» группы."
L["Its groups come from Arc UI's shared layout '%s'."] = "Его группы взяты из общего макета Arc UI «%s»."
L["Its layout is locked, so it stays put anyway."] = "Его макет закреплен, поэтому он все равно остается на месте."
L["Its look"] = "Его вид"
