L["Its own icon"] = "Свой значок"
L["Its own key, ping only"] = "Своя клавиша, только пинг"
L["Its own spot"] = "Свое место"
L["Its own spot, or riding another frame: it follows that frame and goes back to its own spot while the frame is not on screen."] = "Свое место или поверх другого фрейма: следует за ним и возвращается на свое место, пока фрейма нет на экране."
L["Its point"] = "Его точка"
L["Its reminders and their pulse, sound and glow."] = "Его напоминания, их пульсация, звук и свечение."
L["Its rules (the Triggers tab) start its timer and count its stacks from events you pick."] = "Его правила (вкладка «Триггеры») запускают его таймер и считают его стаки по выбранным вами событиям."
L["Its rules are below."] = "Его правила ниже."
L["Its rules are on the Triggers tab: they start its timer and count its stacks."] = "Его правила на вкладке «Триггеры»: они запускают его таймер и считают его стаки."
L["Its rules go on the Triggers tab once it is made."] = "Его правила появятся на вкладке «Триггеры», когда он будет создан."
L["Its rules on the Triggers tab start its timer and count its stacks."] = "Правила на вкладке «Триггеры» запускают его таймер и считают его стаки."
