L["Lights for any enchant on the weapon: an imbue, a poison, an oil or a stone."] = "Загорается при любых чарах на оружии: наложении, яде, масле или камне."
L["Lights the moment you cast, timed from the cast, until it lands in its slot. Needs one cast out of combat to learn its time."] = "Загорается в момент применения, отсчет от применения, пока не займет ячейку. Нужно одно применение вне боя, чтобы узнать длительность."
L["Lights up an icon the moment you press its button, cast it from a macro or use a trinket."] = "Зажигает значок в момент нажатия его кнопки, применения из макроса или использования аксессуара."
