L["Loads only once you know %s. Not known now."] = "Загружается, только когда вы знаете %s. Сейчас неизвестно."
L["Loads only while EVERY checked condition is true. Unloaded, it is fully gone, and returns when that changes, in combat too."] = "Загружается, только пока выполняется КАЖДОЕ отмеченное условие. Когда не загружено, исчезает полностью и возвращается, когда это меняется, в том числе в бою."
L["Loads only while EVERY checked condition is true. Unloaded, it is hidden and returns when that changes. Aura sounds still play."] = "Загружается, только пока выполняется КАЖДОЕ отмеченное условие. Когда не загружено, скрыто и возвращается, когда это меняется. Звуки ауры по-прежнему воспроизводятся."
L["Loads only while at least one checked condition is true. Unloaded, it is fully gone, and returns when that changes, in combat too."] = "Загружается, только пока выполняется хотя бы одно отмеченное условие. Когда не загружено, исчезает полностью и возвращается, когда это меняется, в том числе в бою."
L["Loads only while at least one checked condition is true. Unloaded, it is hidden and returns when that changes. Aura sounds still play."] = "Загружается, только пока выполняется хотя бы одно отмеченное условие. Когда не загружено, скрыто и возвращается, когда это меняется. Звуки ауры по-прежнему воспроизводятся."
L["Loads only while you don't know %s."] = "Загружается, только пока вы не знаете %s."
L["Loads only while you don't know %s. Known now."] = "Загружается, только пока вы не знаете %s. Сейчас известно."
L["Loads only while you don't know %s. Not known now."] = "Загружается, только пока вы не знаете %s. Сейчас неизвестно."
L["Loads only while you wear at least %d of %s (%d worn now)."] = "Загружается, только пока вы носите не менее %d из %s (сейчас надето: %d)."
