L["Off keeps its settings, greyed out."] = "Выкл. сохраняет его настройки, но они неактивны."
L["Off puts the newest entry at the bottom, and the window grows upward."] = "Выкл.: новая запись внизу, окно растет вверх."
L["Off-hand"] = "Левая рука"
