L["Off-hand style"] = "Стиль левой руки"
L["Off. Tick the box at the top of the card to change these."] = "Выкл. Отметьте флажок вверху карточки, чтобы изменить их."
L["Off: a Nature wolf's arrival counts as the proc. On: the Cooldown Manager's Doom Winds icon does, so keep it shown there."] = "Выкл.: прок засчитывается при появлении волка Природы. Вкл.: засчитывается значок «Ветра рока» в Трекере восстановления, поэтому оставьте его там отображаемым."
L["Off: a recharging point is its own color at half brightness."] = "Выкл.: перезаряжающаяся точка получает собственный цвет вполовину яркости."
L["Off: an icon not yet reached is greyed out."] = "Выкл.: значок, до которого еще не дошло, обесцвечен."
L["Off: every %s loads them, each by its own specs and talents. Cast bars always stay on %s."] = "Выкл.: они загружаются на каждом персонаже (%s) по своим специализациям и талантам. Индикаторы заклинаний всегда остаются на %s."
L["Off: no ready check picker, group message or interrupt alert in this spec. Your macros still update."] = "Выкл.: в этой специализации нет окна выбора при проверке готовности, сообщения группе и сигнала прерывания. Ваши макросы по-прежнему обновляются."
L["Off: silent while you are in a party."] = "Выкл.: тихо, пока вы в группе."
L["Off: silent while you are in a raid group."] = "Выкл.: тихо, пока вы в рейде."
L["Off: silent while you are not in a group."] = "Выкл.: тихо, пока вы не в группе."
L["Off: the bar shows its no-band look while the target is in this band."] = "Выкл.: полоса показывает вид «без диапазона», пока цель в этом диапазоне."
L["Off: this trigger plays its sound or speech only, with no pulse."] = "Выкл.: этот триггер проигрывает только звук или речь, без пульсации."
L["Off: this trigger pulses silently. A new trigger starts silent."] = "Выкл.: этот триггер пульсирует без звука. Новый триггер начинается без звука."
L["Offset X"] = "Смещение X"
L["Offset Y"] = "Смещение Y"
L["On %s."] = "На: %s."
L["On a nameplate the bar hides while this window is open; the preview shows it."] = "На индикаторе здоровья полоса скрывается, пока открыто это окно; просмотр ее показывает."
L["On a ready check"] = "При проверке готовности"
L["On anchor %d, %s."] = "На привязке %d, %s."
L["On cooldown"] = "На восстановлении"
L["On cooldown alpha"] = "Непрозрачность на восстановлении"
L["On cooldown opacity starts near the end"] = "Непрозрачность на восстановлении начинается ближе к концу"
L["On cooldown starts with this many seconds left"] = "«На восстановлении» начинается, когда осталось столько секунд"
L["On cooldown too"] = "Даже на восстановлении"
L["On cooldown's opacity waits until little time is left; before that the icon takes Before that's opacity."] = "Непрозрачность «На восстановлении» ждет, пока останется мало времени; до этого значок берет непрозрачность «До этого»."
L["On it now: %s."] = "Сейчас на нем: %s."
L["On proc"] = "При проке"
L["On proc (proc glow turns on)"] = "При проке (включается свечение прока)"
L["On ranked realms, follow whichever rank of this spell you know now."] = "На мирах с рангами: следовать тому рангу этого заклинания, который вы знаете сейчас."
L["On ranked realms, read whichever rank of this spell you know now."] = "На мирах с рангами: читать тот ранг этого заклинания, который вы знаете сейчас."
L["On ranked realms, track whichever rank of this spell you currently know. Re-resolves on spell changes."] = "На мирах с рангами: отслеживать тот ранг этого заклинания, который вы знаете сейчас. Определяется заново при смене заклинаний."
L["On screen"] = "На экране"
L["On the Cooldown Manager icon for %s."] = "На значке Трекера восстановления для: %s."
L["On the Cooldown Manager icon of %s."] = "На значке Трекера восстановления: %s."
L["On the Cooldown Manager icon with cooldown ID %s."] = "На значке Трекера восстановления с ID восстановления %s."
L["On the action button holding %s (%s)."] = "На кнопке панели команд с %s (%s)."
L["On the action button holding %s."] = "На кнопке панели команд с %s."
L["On the action button with %s."] = "На кнопке панели команд с %s."
L["On the bar"] = "На полосе"
L["On the group"] = "На группе"
L["On the icon"] = "На значке"
L["On the icon with cooldown ID %s."] = "На значке с ID восстановления %s."
L["On this icon"] = "На этом значке"
L["On top"] = "Сверху"
L["On unit"] = "На юните"
L["On use (when cast)"] = "При использовании (при применении)"
L["On your screen"] = "На вашем экране"
L["On: adding stacks also starts the timer over, with the seconds below."] = "Вкл.: добавление стаков также запускает таймер заново, с секундами ниже."
L["On: every Arc Proc resets the moment a key starts, so a reset is never missed. Off: on the gate drop, which keeps the skip working."] = "Вкл.: каждый Arc Proc сбрасывается в момент начала ключа, поэтому сброс не пропускается. Выкл.: при падении шлюза, что сохраняет работу пропуска."
L["On: icons pack (Show while missing ones too). Off: every aura keeps its spot."] = "Вкл.: значки уплотняются (включая «Показывать, пока отсутствует»). Выкл.: каждая аура сохраняет свое место."
L["On: it glows while this look shows. Click to switch it."] = "Вкл.: светится, пока показан этот вид. Щелкните, чтобы переключить."
L["On: the debuffs start on the line after the buffs. Off: they follow straight on."] = "Вкл.: отрицательные эффекты начинаются на строке после положительных. Выкл.: они идут сразу следом."
L["On: the rule fires only while the conditions below hold. Off drops them."] = "Вкл.: правило срабатывает, только пока выполняются условия ниже. Выкл. убирает их."
L["On: the skin sets it for every bar that wears it. Off: each bar keeps its own."] = "Вкл.: скин задает это для каждой полосы, которая его использует. Выкл.: у каждой полосы остается свое."
L["On: the spell's own requirement decides (a proc, enough mana), even on cooldown. Off: only when it can be cast now."] = "Вкл.: решает собственное условие заклинания (прок, достаточно маны), даже во время восстановления. Выкл.: только когда его можно применить сейчас."
L["On: the trigger fires for your pet's casts of the spell as well as yours."] = "Вкл.: триггер срабатывает и на применения заклинания вашим питомцем, и на ваши."
L["On: this opacity while none is left. Off: it keeps its opacity."] = "Вкл.: эта непрозрачность, пока ничего не осталось. Выкл.: сохраняет свою непрозрачность."
L["On: this opacity while toggled on. Off: it keeps its opacity."] = "Вкл.: эта непрозрачность, пока включено. Выкл.: непрозрачность не меняется."
L["On: this trigger has its own pulse duration and animation tuning. Off drops them, and the reminder's apply."] = "Вкл.: у этого триггера своя длительность пульсации и настройка анимации. Выкл. сбрасывает их, и применяются настройки напоминания."
L["Once an ability is off cooldown."] = "Когда способность вышла с восстановления."
L["Once the proc glow goes, the pulse this trigger started leaves the screen, the queue and the hold."] = "Когда свечение прока пропадает, пульсация, запущенная этим триггером, уходит с экрана, из очереди и из удержания."
L["Once the spell stops being usable, the pulse this trigger started leaves the screen, the queue and the hold."] = "Когда заклинание перестает быть доступным, пульсация, запущенная этим триггером, уходит с экрана, из очереди и из удержания."
L["One card per element with its preview, kind, load conditions, Edit and Delete."] = "Одна карточка на элемент: просмотр, тип, условия загрузки, «Изменить» и «Удалить»."
L["One color"] = "Один цвет"
L["One editor for every selected icon (or bar): the rows they all share, read from the first one; a change lands on all of them."] = "Один редактор для всех выбранных значков (или полос): общие для них строки, значения берутся с первого; изменение применяется ко всем."
L["One layer for every element of this layout, or each element's own layer moved up or down."] = "Один слой для всех элементов этого макета или собственный слой каждого элемента, сдвинутый вверх или вниз."
L["One look"] = "Один вид"
L["One motion (seconds)"] = "Одно движение (с)"
L["One option of a choice talent"] = "Один из вариантов таланта с выбором"
L["One per tick"] = "По одному на тик"
L["One pulse (seconds)"] = "Одна пульсация (с)"
L["One run (seconds)"] = "Один проход (с)"
L["One setup for all your characters, and your kick macros become account macros. Your kick spell stays per character."] = "Одна настройка для всех ваших персонажей, а макросы кика становятся общими для аккаунта. Заклинание кика остается за персонажем."
L["One stance"] = "Одна стойка"
L["One totem, by its spell ID"] = "Один тотем, по ID его заклинания"
L["One totem: any rank, any slot. A totem slot: whatever is in it. My totem bar's pick: its totem, shown with none down; click drops it."] = "Один тотем: любой ранг, любая ячейка. Ячейка тотема: все, что в ней. Выбор моей панели тотемов: ее тотем, показанный, пока ни один не стоит; щелчок ставит его."
L["One you have not learned yet stays grey until you do."] = "Неизученный остается серым, пока вы его не изучите."
L["One-time catch-up: moves EVERY action bar spell to the top rank you know, including lower ranks you placed on purpose."] = "Разовое выравнивание: переносит КАЖДОЕ заклинание на панелях команд на высший известный вам ранг, включая низшие ранги, которые вы поставили намеренно."
L["Only a spell row has a cost to mark."] = "Метку затрат имеет только строка заклинания."
L["Only fire when proc is active"] = "Срабатывать, только когда прок активен"
L["Only if"] = "Только если"
L["Only if it is not running"] = "Только если он не идет"
L["Only in combat"] = "Только в бою"
L["Only load once learned"] = "Загружать только после изучения"
L["Only load while this hand holds a weapon"] = "Загружать, только пока в этой руке оружие"
L["Only new"] = "Только новые"
L["Only new %s"] = "Только новые: %s"
L["Only new ones"] = "Только новые"
L["Only on %s"] = "Только на %s"
L["Only on-use trinkets (hide passive ones)"] = "Только используемые аксессуары (скрыть пассивные)"
L["Only out of combat"] = "Только вне боя"
L["Only the spells I pick"] = "Только выбранные мной заклинания"
L["Only the types ticked under Tracking, Dispel types, show, so only they have an icon."] = "Показываются только типы, отмеченные в «Отслеживание», «Типы развеивания», поэтому только у них есть значок."
L["Only this character"] = "Только этот персонаж"
L["Only this rank"] = "Только этот ранг"
L["Only what I changed"] = "Только то, что я изменил"
L["Only what loads here"] = "Только то, что загружается здесь"
L["Only what loads on this character"] = "Только то, что загружается на этом персонаже"
L["Only when out of stock"] = "Только при отсутствии запаса"
L["Only when someone calls your marker"] = "Только когда кто-то называет вашу метку"
L["Only while holding Shift"] = "Только при зажатом Shift"
L["Only while on cooldown"] = "Только на восстановлении"
L["Only while ready"] = "Только когда готово"
L["Only while this window is open"] = "Только пока открыто это окно"
L["Only your own"] = "Только ваши"
L["Only your own copy of the aura shows, not another player's."] = "Показывается только ваша копия ауры, а не другого игрока."
L["Opacity"] = "Непрозрачность"
L["Opacity at that count"] = "Непрозрачность при этом числе"
L["Open"] = "Открыть"
