L["Open my copy"] = "Открыть мою копию"
L["Open the marker picker"] = "Открывать окно выбора метки"
L["Open world"] = "Открытый мир"
L["Opens Active while on Tracking, which decides when this state holds."] = "Открывает «Активно, пока» на вкладке «Отслеживание»: оно определяет, когда действует это состояние."
L["Opens Import / Export with exactly this selection ticked and its share string ready to copy."] = "Открывает «Импорт / Экспорт» с точно этим выбором и готовой к копированию строкой."
L["Opens Import / Export with just this reminder ticked and its share string ready to copy."] = "Открывает «Импорт / Экспорт» с отмеченным только этим напоминанием и готовой к копированию строкой."
L["Opens Import / Export with just this ticked and its share string ready to copy."] = "Открывает «Импорт / Экспорт» с отмеченным только этим и готовой к копированию строкой."
L["Opens a picker for this group's spells and items right after Create. Out of combat only."] = "Сразу после «Создать» открывает выбор заклинаний и предметов этой группы. Только вне боя."
L["Opens every More options fold in the editors, so the fine-tuning rows show without a click. Off: they wait behind their fold."] = "Раскрывает все блоки «Еще параметры» в редакторах, поэтому строки тонкой настройки видны без щелчка. Выкл.: они ждут за своим блоком."
L["Opens it. The Anchor panel on its Position tab holds the link back to this one."] = "Открывает его. Панель привязки на его вкладке «Позиция» содержит ссылку обратно на этот."
L["Opens its editor."] = "Открывает его редактор."
L["Opens the Add window aimed at this element."] = "Открывает окно добавления, нацеленное на этот элемент."
L["Opens the Add window for a spell, an item, a weapon enchant or a missing aura to be reminded of."] = "Открывает окно добавления заклинания, предмета, чар оружия или отсутствующей ауры для напоминания."
L["Opens the talent tree: click a talent for this rule, again for Not taken."] = "Открывает дерево талантов: щелкните талант для этого правила, еще раз - «Не взят»."
L["Opens the talent tree: the bar keeps one look while you have the talent you pick, one while you don't."] = "Открывает дерево талантов: у полосы один вид, пока у вас есть выбранный талант, и другой, пока его нет."
L["Optional"] = "Необязательно"
L["Or type a spell ID"] = "Или введите ID заклинания"
