L["Puts back what the update changed, added or removed. Your changes since to the items it changed go too."] = "Возвращает то, что обновление изменило, добавило или убрало. Ваши последующие изменения тех элементов, которые оно изменило, тоже сбрасываются."
L["Puts each layout's bars and free icons in the sidebar under BARS and FREE ICONS folds. Off: they list in place among its groups."] = "Помещает полосы и свободные значки каждого макета в боковой панели под блоки «ПОЛОСЫ» и «СВОБОДНЫЕ ЗНАЧКИ». Выкл.: они перечисляются на месте среди его групп."
L["Puts it back at once when the game or another addon moves it. Off: it goes back the next time the group moves."] = "Возвращает на место сразу, когда игра или другой аддон перемещает его. Выкл.: возвращается при следующем перемещении группы."
