L["Text color outside the thresholds"] = "Цвет текста вне порогов"
L["Text element"] = "Текстовый элемент"
L["Text font"] = "Шрифт текста"
L["Text in the band's color"] = "Текст цвета диапазона"
L["Text outline"] = "Контур текста"
L["Text shadow"] = "Тень текста"
L["Text size"] = "Размер текста"
L["Text threshold %d color"] = "Цвет порога текста %d"
L["Text threshold %d value"] = "Значение порога текста %d"
L["Text threshold colors"] = "Цвета порогов текста"
L["Text thresholds in power units"] = "Пороги текста в единицах ресурса"
L["Text to Speech"] = "Текст в речь"
L["Text to speech: when set, it is spoken instead of the sound."] = "Текст в речь: если задан, произносится вместо звука."
L["Text type"] = "Тип текста"
L["Texts"] = "Тексты"
L["Texts take the bar's color"] = "Тексты берут цвет полосы"
L["Texture"] = "Текстура"
L["Texture  -  %s"] = "Текстура  -  %s"
L["Texture name"] = "Название текстуры"
L["Textures"] = "Текстуры"
L["Textures you use show here."] = "Здесь показываются используемые вами текстуры."
L["That anchor target no longer exists, so it stays free."] = "Этой цели привязки больше нет, поэтому значок остается свободным."
L["That frame can't move this way: an Arc Auras frame, the whole screen, or what this group is anchored to."] = "Этот фрейм нельзя перемещать так: это фрейм Arc Auras, весь экран или то, к чему привязана эта группа."
L["That is not a spell ID."] = "Это не ID заклинания."
L["That paste came in cut short. Paste it once more."] = "Вставка оказалась обрезанной. Вставьте еще раз."
L["The "] = "Вид: "
L["The Active look, its timer running with its swipe and duration text. Drag any text on the icon to place it."] = "Вид «Активно» с идущим таймером, его затемнением и текстом длительности. Перетащите любой текст на значке, чтобы разместить."
L["The Algeth'ar Puzzle Box's haste: 20 seconds from its use; dying clears it."] = "Скорость от Алгет'арской головоломки: 20 секунд с момента использования; смерть сбрасывает."
L["The Arc Proc's own"] = "Собственный у Arc Proc"
L["The Cooldown Manager look draws the border and the shadow."] = "Рамку и тень рисует вид Трекера восстановления."
L["The Cooldown Manager look sets the picture's size, crop and shape."] = "Размер, обрезку и форму картинки задает вид Трекера восстановления."
L["The Cooldown Manager's cooldown IDs for spells, auras and trinkets, one line per category. Runs of IDs show as ranges."] = "ID из Трекера восстановления для заклинаний, аур и аксессуаров, по одной строке на категорию. Подряд идущие ID показываются диапазонами."
L["The Cooldown Manager's soft shadow frame around the icon art."] = "Мягкая теневая рамка Трекера восстановления вокруг рисунка значка."
L["The ID block shows only when Shift is held as the tooltip opens."] = "Блок ID показывается, только если Shift зажат в момент открытия подсказки."
L["The ID of what the tooltip shows: a spell, aura, item, toy, mount, currency, achievement or quest."] = "ID того, что показывает подсказка: заклинания, ауры, предмета, игрушки, транспорта, валюты, достижения или задания."
L["The Light's Potential potion: 30 seconds from the drink, each drink restarts it; dying clears it."] = "Зелье «Потенциал Света»: 30 секунд с момента приема, каждый прием запускает заново; смерть сбрасывает."
L["The Not active look, with no timer running."] = "Вид «Не активно» без идущего таймера."
L["The On cooldown look: the timer idle and its cooldown spell cooling down."] = "Вид «На восстановлении»: таймер простаивает, а его заклинание восстанавливается."
L["The Ready look: the timer idle and its cooldown spell ready."] = "Вид «Готово»: таймер простаивает, а его заклинание готово."
L["The Timer running look, its timer frozen with its swipe and duration text. Drag any text on the icon to place it."] = "Вид «Таймер идет» с остановленным таймером, его затемнением и текстом длительности. Перетащите любой текст на значке, чтобы разместить."
L["The Tracked Bars entry this bar copies. Keep the Cooldown Manager's own bar on, and hide it with opacity 0 in Edit Mode."] = "Запись из «Отслеживаемых полос эффектов», которую копирует эта полоса. Оставьте собственную полосу Трекера восстановления включенной и скройте ее непрозрачностью 0 в режиме редактирования."
L["The action bar's yellow check on the icon while it waits for your next swing."] = "Желтая галочка панели команд на значке, пока он ждет вашего следующего удара."
L["The art's spell"] = "Заклинание рисунка"
L["The aura at 3 stacks."] = "Аура с 3 стаками."
L["The aura comes up with a fake duration (swipe and duration text), drops to its missing look, and comes back."] = "Аура появляется с условной длительностью (затемнение и текст длительности), переходит в вид отсутствия и возвращается."
L["The aura counts down, drops off, and comes back: threshold colours and the duration text."] = "Аура отсчитывает время, пропадает и возвращается: цвета порогов и текст длительности."
L["The aura icons in this group are kept for when you switch back."] = "Значки аур этой группы сохраняются на случай, если вы переключитесь обратно."
L["The aura lasts"] = "Аура длится"
L["The aura lasts (seconds)"] = "Аура длится (секунды)"
L["The aura with 60% of its duration left."] = "Аура с оставшимися 60% длительности."
L["The aura's full length, which the game keeps from addons: seconds need it, percent does not. 0 = not set: always shown."] = "Полная длительность ауры, которую игра скрывает от аддонов: для секунд она нужна, для процентов нет. 0 = не задано: показывается всегда."
L["The aura's full length. The game hides it from addons, so seconds thresholds need it. 0 = not set: the glow shows the whole time."] = "Полная длительность ауры. Игра скрывает ее от аддонов, поэтому она нужна для порогов в секундах. 0 - не задано: свечение показывается все время."
L["The aura's icon"] = "Значок ауры"
L["The aura's spell ID, or the spell whose cooldown it follows: an ID, a link or the name of a spell you know. Enter applies it."] = "ID заклинания ауры или заклинания, за чьим восстановлением она следует: ID, ссылка или название известного вам заклинания. Enter применяет."
L["The aura's spell IDs, comma separated."] = "ID заклинаний ауры через запятую."
L["The aura's spell IDs, comma separated. Any caster's copy counts."] = "ID заклинаний ауры через запятую. Учитывается копия от любого источника."
L["The aura's spell IDs, separated by commas or spaces. Add every rank's ID if they differ. The game shows whichever is up."] = "ID заклинаний ауры через запятую или пробел. Добавьте ID каждого ранга, если они различаются. Игра показывает тот, что действует."
L["The aura's spell IDs, separated by commas or spaces. Tracking sets its unit."] = "ID заклинаний ауры через запятую или пробел. Юнита задает «Отслеживание»."
L["The aura's spell IDs, separated by commas or spaces; any of them counts."] = "ID заклинаний ауры через запятую или пробел; учитывается любой из них."
L["The aura's spell IDs, separated by commas or spaces; any of them shows the picture."] = "ID заклинаний ауры через запятую или пробел; любой из них показывает картинку."
L["The aura's spell IDs, separated by commas. A debuff usually has the ID of the spell that puts it up."] = "ID заклинаний ауры через запятую. У отрицательного эффекта обычно ID заклинания, которое его накладывает."
L["The band your target is in; blank with no target or a friendly one."] = "Диапазон, в котором находится ваша цель; пусто, если цели нет или она дружественная."
L["The bar"] = "Полоса"
L["The bar at 3 stacks, or at its Max stacks when that is lower."] = "Полоса с 3 стаками или с максимумом стаков, если он меньше."
L["The bar at 60%, standing still."] = "Полоса на 60%, неподвижно."
L["The bar between swings."] = "Полоса между ударами."
L["The bar in the middle of a cast, standing still."] = "Полоса посреди применения, неподвижно."
L["The bar is full at this many stacks. Empty: the maximum the game reports, shown in the field. Type a number only if it is wrong."] = "Полоса заполнена при таком числе стаков. Пусто: максимум, о котором сообщает игра, он показан в поле. Вводите число, только если он неверен."
L["The bar part way through its timer."] = "Полоса на середине таймера."
L["The bar shows half the power; past the middle it fills again in the second half color."] = "Полоса показывает половину ресурса; за серединой она заполняется снова цветом второй половины."
L["The bar when the reload is done but you are moving: the shot waits for you to stop."] = "Полоса, когда перезарядка закончена, но вы двигаетесь: выстрел ждёт, пока вы остановитесь."
L["The bar with no timer running."] = "Полоса без идущего таймера."
L["The bar's look."] = "Вид полосы."
L["The bar's own look"] = "Собственный вид полосы"
L["The bars that wear it keep its look as their own."] = "Полосы, использующие его, сохраняют его вид как свой."
L["The border always shows while the window is unlocked."] = "Рамка всегда показана, пока окно не закреплено."
L["The brief lock some charge spells have after each cast never greys the icon. Longer locks still show."] = "Короткая блокировка некоторых заклинаний с зарядами после каждого применения не обесцвечивает значок. Более долгие блокировки по-прежнему видны."
L["The buff this totem gives you, as its tooltip names it. The Out of range look shows while the totem is out and you lack it."] = "Положительный эффект от этого тотема, как он назван в подсказке. Вид «Вне дальности» показывается, пока тотем стоит, а у вас этого эффекта нет."
L["The chance climbs 1% per Riptide since the last proc."] = "Шанс растет на 1% за каждую «Быстрину» после последнего прока."
L["The chance climbs per qualifying harvest; needs the 2-piece set."] = "Шанс растет с каждым подходящим сбором; нужен комплект из 2 предметов."
L["The chance of a proc"] = "Шанс прока"
L["The class this skin switches on for."] = "Класс, для которого включается этот скин."
L["The color %s."] = "Цвет: %s."
L["The cooldown lasts (seconds)"] = "Восстановление длится (секунды)"
L["The cooldown swipe keeps its own opacity while the icon dims, so only the art fades."] = "Затемнение восстановления сохраняет свою непрозрачность, пока значок тускнеет, поэтому блекнет только рисунок."
L["The count"] = "Число"
L["The count of your equipped ammo; blank with the slot empty."] = "Число надетых боеприпасов; пусто, если ячейка пуста."
L["The count the \"Ammo is low\" load and visibility condition uses. An icon's warning glow and ammo count colors have their own thresholds."] = "Число, которое использует условие загрузки и видимости «Боеприпасы на исходе». У предупреждающего свечения значка и цветов числа боеприпасов свои пороги."
L["The countdown stays hidden until this many seconds are left."] = "Отсчет скрыт, пока не останется столько секунд."
L["The deck half drawn, with a mark where each proc landed."] = "Колода, разыгранная наполовину, с меткой там, где выпал каждый прок."
L["The dim copy stays when the picture hides: no aura, no timer, a cooldown not ready."] = "Тусклая копия остается, когда картинка скрывается: нет ауры, нет таймера, восстановление не готово."
L["The end of your cast that your connection's delay covers: start the next cast once the fill reaches it."] = "Конец вашего применения, который покрывает задержка соединения: начинайте следующее применение, как только заполнение дойдет до него."
L["The fill behind this group while the options window is open; opacity 0 means none."] = "Заливка за этой группой, пока открыто окно параметров; непрозрачность 0 - без заливки."
L["The fill shows how many of this deck's procs are used: none, some or all. Off: the Fill color."] = "Заполнение показывает, сколько проков этой колоды использовано: ни одного, часть или все. Выкл.: «Цвет заполнения»."
L["The first time you log in after Arc Auras updates, a window opens once with what changed in the new version."] = "При первом входе после обновления Arc Auras один раз открывается окно с изменениями в новой версии."
L["The full look starts out of combat, or after a /reload."] = "Полный вид запускается вне боя или после /reload."
L["The game does not let addons match this aura type on that unit by spell ID."] = "Игра не позволяет аддонам сопоставлять этот тип ауры на этом юните по ID заклинания."
L["The game draws it with the aura, in combat too. Buffs work on you, your pet and friendly units; debuffs on a hostile target or focus."] = "Игра рисует его вместе с аурой, в том числе в бою. Положительные эффекты работают на вас, вашем питомце и дружественных юнитах; отрицательные - на враждебной цели или запомненной цели."
L["The game frame's name, as Pick Frame shows it. Enter applies it."] = "Название фрейма игры в том виде, как его показывает «Выбрать фрейм». Enter применяет."
L["The game holds this frame still in combat. It moves when combat ends."] = "Игра не дает перемещать этот фрейм в бою. Он переместится, когда бой закончится."
L["The game keeps an aura's length from addons, so seconds need it. A share needs none."] = "Игра скрывает от аддонов длительность ауры, поэтому для секунд она нужна. Для доли - нет."
L["The game keeps the aura's length from addons: 0 shows the words the whole time it is up."] = "Игра скрывает от аддонов длительность ауры: 0 показывает слова все время, пока она действует."
L["The game plays aura sounds itself, so they work in combat, for anyone's copy of the aura."] = "Звуки аур проигрывает сама игра, поэтому они работают в бою, для копии ауры от любого источника."
L["The game plays it, in combat too; Load When and the gap between cues don't apply."] = "Его проигрывает игра, в том числе в бою; «Загружать, когда» и пауза между сигналами не действуют."
L["The game protects %s, so it stays free."] = "Игра защищает %s, поэтому значок остается свободным."
L["The game sent a spell update"] = "Игра прислала обновление заклинаний"
L["The game's Enable Pings or Show Pings in Chat setting is off, so no pings reach the feed."] = "Параметр игры «Включить пинги» или «Показывать пинги в чате» выключен, поэтому пинги не попадают в ленту."
L["The game's clock, as the minimap shows it."] = "Часы игры, как их показывает миникарта."
L["The game's debuff border"] = "Рамка отрицательных эффектов игры"
L["The game's own cooldown and buff icons and bars, as in its options. Items pinned to its icons stand free until it is back on."] = "Собственные значки и полосы восстановлений и эффектов игры, как в ее параметрах. Элементы, закрепленные за его значками, остаются свободными, пока он не включится снова."
L["The game's own gold art, untinted, so the color steps aside. Intensity still applies."] = "Собственный золотой рисунок игры без оттенка, поэтому цвет не действует. Интенсивность по-прежнему применяется."
L["The global name of a frame, e.g. ElvUF_Player. A frame that does not exist counts as not there."] = "Глобальное название фрейма, например ElvUF_Player. Несуществующий фрейм считается отсутствующим."
L["The global name of a game frame, e.g. PlayerFrame or ElvUF_Player."] = "Глобальное название фрейма игры, например PlayerFrame или ElvUF_Player."
L["The glow waits for combat; out of combat the bar shows without it."] = "Свечение ждет боя; вне боя полоса показывается без него."
L["The glow waits for combat; out of combat the icon shows without it."] = "Свечение ждет боя; вне боя значок показывается без него."
L["The green outline and dark fill around each group while this window is open. Nothing shows groups as in play. Name tabs still work."] = "Зеленый контур и темная заливка вокруг каждой группы, пока это окно открыто. «Ничего» показывает группы как в игре. Вкладки с названиями по-прежнему работают."
L["The group"] = "Группа"
L["The group takes its %s with it."] = "Группа забирает с собой: %s."
L["The group's box hugs the icons that are showing; anything anchored to it moves with it."] = "Рамка группы облегает показанные значки; все, что к ней привязано, движется вместе с ней."
L["The group's point"] = "Точка группы"
L["The group's spot can't be read right now. The frame moves once it can."] = "Место группы сейчас не прочитать. Фрейм переместится, когда это станет возможно."
L["The groups take their %s with them."] = "Группы забирают с собой: %s."
L["The health preview: 65% health with incoming heals and shields, in your colours and texts."] = "Просмотр здоровья: 65% здоровья с входящим лечением и щитами, в ваших цветах и текстах."
L["The icon"] = "Значок"
L["The icon and bar previews sit on this color."] = "Просмотры значков и полос лежат на этом цвете."
L["The icon as the game's Cooldown Manager draws it: its rounded corners, its border and shadow, and its swipe."] = "Значок в том виде, как его рисует Трекер восстановления игры: скругленные углы, рамка, тень и затемнение."
L["The icon's art and border at this opacity while the rule holds. 0% hides the whole icon, texts and glows too."] = "Рисунок и рамка значка с этой непрозрачностью, пока правило выполняется. При 0% скрываются весь значок, тексты и свечение."
L["The icon's cooldown ID, its exact entry in the Cooldown Manager: Pick Frame on an icon fills it. Empty uses the spell above."] = "ID восстановления значка, его точная запись в Трекере восстановления: «Выбрать фрейм» на значке заполняет его. Пусто: используется заклинание выше."
L["The icon's exact entry in the Cooldown Manager; Pick Frame on an icon fills it. Empty uses the spell above."] = "Точная запись значка в Трекере восстановления; «Выбрать фрейм» на значке заполняет ее. Пусто - заклинание выше."
L["The icon's file ID, the base icon when an override swapped the art, and the icon the button shows when that differs."] = "ID файла значка, базовый значок, когда рисунок заменен, и значок, который показывает кнопка, если он отличается."
L["The import did not run."] = "Импорт не выполнился."
L["The internal cooldown as a timer: 45 s, less with Natural Harmony."] = "Внутреннее восстановление как таймер: 45 с, меньше с «Гармония стихий»."
L["The item"] = "Предмет"
L["The item's own stacks, before this rule acts. Empty = no such condition."] = "Собственные стаки предмета до срабатывания этого правила. Пусто = такого условия нет."
L["The item, or several: the icon shows the first one you carry and can use."] = "Предмет или несколько: значок показывает первый, который у вас есть и который можно использовать."
L["The items that used the old values take the new ones."] = "Элементы, использовавшие старые значения, берут новые."
L["The items you have keep their look; only new ones start with these. Leaving the page does the same."] = "Имеющиеся у вас элементы сохраняют вид; с этими значениями начинаются только новые. То же происходит при уходе со страницы."
L["The kinds that take this page's rows, each where it has the row. Nothing happens until you press Copy."] = "Виды, которые принимают строки этой страницы, каждый там, где у него есть строка. Ничего не происходит, пока вы не нажмете «Копировать»."
L["The label's own color"] = "Собственный цвет подписи"
L["The last 0.5 s of the bar is Auto Shot's windup: it fills only while you stand still. Colors on the Appearance tab."] = "Последние 0,5 с полосы: прицеливание автоматической стрельбы. Оно заполняется, только пока вы стоите на месте. Цвета на вкладке «Внешний вид»."
L["The layout's center point"] = "Центральная точка макета"
L["The layout's distance from the spot it's pinned to, in whole units."] = "Расстояние макета от места, за которым он закреплен, в целых единицах."
L["The line to speak."] = "Строка для произнесения."
L["The look the rows below change. The bar shows it while you edit; anything a look leaves alone follows the bar's own."] = "Вид, который меняют строки ниже. Полоса показывает его, пока вы правите; все, чего вид не касается, следует собственным настройкам полосы."
L["The look the rows below edit. Bar's own applies when no skin does. A skin applies when its conditions hold, first from the top."] = "Вид, который правят строки ниже. «Свой у полосы» действует, когда не подходит ни один скин. Скин действует, когда выполнены его условия; побеждает первый сверху."
L["The look while the aura is missing: the ghost with its Missing icon, alpha and desaturation."] = "Вид, пока ауры нет: призрак с его значком «Отсутствует», непрозрачностью и обесцвечиванием."
L["The look while the aura is up: Aura Active art, alpha, tint, border and glow. Drag any text to place it."] = "Вид, пока аура действует: изображение «Аура активна», непрозрачность, оттенок, рамка и свечение. Перетащите любой текст, чтобы разместить его."
L["The look while the aura is up: its button over the cooldown, in the Aura Active look, with stacks. Drag texts to place them."] = "Вид, пока аура действует: ее кнопка поверх восстановления в виде «Аура активна», со стаками. Перетащите тексты, чтобы разместить их."
L["The look while you are in the stance (any stance, for your current one). Drag any text on the icon to place it."] = "Вид, пока вы в стойке (в любой, для текущей стойки). Перетащите любой текст на значке, чтобы разместить."
L["The look while you are not in it (no stance, for your current one)."] = "Вид, пока вы не в ней (без стойки, для текущей стойки)."
L["The macro this keeps updated. A new name takes over when you save."] = "Макрос, который это поддерживает в актуальном состоянии. Новое название вступит в силу при сохранении."
L["The mana the next tick adds glows past the fill, brightens as the tick nears, then lands. Empty while the five-second rule runs."] = "Мана, которую добавит следующий тик, светится за заполнением, ярчает по мере приближения тика, затем зачисляется. Пусто, пока действует правило пяти секунд."
L["The marker picker"] = "Окно выбора метки"
L["The marker your kick macros put on your focus and your group message names."] = "Метка, которую макросы кика ставят на запомненную цель и которую называет сообщение группе."
L["The middle of your screen"] = "Середина вашего экрана"
L["The mirror is not loaded."] = "Зеркало не загружено."
L["The move did not run."] = "Перемещение не выполнилось."
L["The nearest band that shows, standing still."] = "Ближайший показываемый диапазон, неподвижно."
L["The new look shows after a reload"] = "Новый вид появится после перезагрузки"
L["The next tick"] = "Следующий тик"
L["The number beside a marker that comes back in a later swing."] = "Число рядом с маркером, который вернется в одном из следующих ударов."
L["The numeric item ID."] = "Числовой ID предмета."
L["The opacity starts with this many seconds left."] = "Непрозрачность начинается, когда остается столько секунд."
L["The original bright cyan."] = "Исходный яркий голубой."
L["The pack items you deleted come back with this update. Unticked, they stay deleted."] = "Удаленные вами элементы набора возвращаются с этим обновлением. Если не отмечено, они остаются удаленными."
L["The pack's name. Whoever imports the string sees it first."] = "Название набора. Тот, кто импортирует строку, увидит его первым."
L["The part of a shield that doesn't fit past full health draws over the end of the health, so a shield on a full-health unit still shows."] = "Часть щита, не помещающаяся за полным здоровьем, рисуется поверх конца здоровья, поэтому щит на юните с полным здоровьем все равно виден."
L["The part of each entry the rows below place."] = "Часть каждой записи, которую размещают строки ниже."
L["The picture again, dimmed, behind it: the empty part of a fill. It hides with the picture."] = "Та же картинка, затемненная, позади нее: пустая часть заполнения. Скрывается вместе с картинкой."
L["The picture as it looks while active; a fill or a ring stands at 60%."] = "Картинка в активном виде; заполнение или кольцо стоят на 60%."
L["The picture grows and shrinks gently, in combat too."] = "Картинка плавно увеличивается и уменьшается, в том числе в бою."
L["The picture is a sheet of frames, played in order over and over."] = "Картинка - лист кадров, которые проигрываются по порядку снова и снова."
L["The picture keeps its shape at any width and height: its edges are cropped, never stretched."] = "Картинка сохраняет форму при любой ширине и высоте: ее края обрезаются, но не растягиваются."
L["The picture, border, swipe, shadow and glows follow the shape."] = "Картинка, рамка, затемнение, тень и свечения следуют форме."
L["The ping key works on every spell you have bound. Turn this on to keep it to the spells you pick on the Spells tab."] = "Клавиша пинга работает для каждого назначенного заклинания. Включите, чтобы ограничить ее заклинаниями, выбранными на вкладке «Заклинания»."
L["The point of the frame that goes on the group."] = "Точка фрейма, которая ставится на группу."
L["The power this row holds on. All powers: whatever power the bar shows."] = "Ресурс, при котором выполняется эта строка. Все ресурсы: любой ресурс, который показывает полоса."
L["The pulse stays at full, with no fade, until you cast the spell or use the item, or its trigger's Clear when ends it."] = "Пульсация остается на полную, без затухания, пока вы не примените заклинание или не используете предмет либо пока ее не завершит «Очищать, когда» триггера."
L["The ready look with no animation. Drag any text on the icon to place it."] = "Вид «Готово» без анимации. Перетащите любой текст на значке, чтобы разместить."
L["The ready look, with the Ready text when it is on."] = "Вид «Готово» с текстом «Готово», если он включен."
L["The reload is done but you are moving: the shot waits for you to stop."] = "Перезарядка закончена, но вы двигаетесь: выстрел ждёт, пока вы остановитесь."
L["The resize lands when you let go of the slider."] = "Изменение размера применяется, когда вы отпускаете ползунок."
L["The resource texts change color at their own power values, apart from the bar's colors."] = "Тексты ресурса меняют цвет при своих значениях ресурса, независимо от цветов полосы."
L["The resource texts wear the fill's color, the bar's own or a row's. A row's own text color wins."] = "Тексты ресурса берут цвет заполнения: собственный цвет полосы или строки. Собственный цвет текста строки главнее."
L["The row holds for any spell left in it."] = "Строка выполняется для любого оставшегося в ней заклинания."
L["The rule fires only while this spell is off its cooldown (the GCD never counts). Empty = no such condition."] = "Правило срабатывает, только пока это заклинание не на восстановлении (GCD не считается). Пусто = такого условия нет."
L["The same enchant counting down, as it looks in play."] = "Те же чары с отсчетом, как это выглядит в игре."
L["The same totem counting down, as it looks in play."] = "Тот же тотем с отсчетом, как это выглядит в игре."
L["The set gate is the Set Pieces Rule on Load Conditions."] = "Условие комплекта - это «Правило частей комплекта» в «Условиях загрузки»."
L["The sets on the gear you wear now are listed; with fewer pieces on, the item goes inert."] = "Перечислены комплекты на надетой сейчас экипировке; при меньшем числе частей предмет перестает работать."
L["The shield is in Appearance > Icon, the color in Appearance > Fill & Colors."] = "Щит находится в «Внешний вид» > «Значок», цвет - в «Внешний вид» > «Заполнение и цвета»."
L["The specs this skin switches on in. Pick several or Any spec."] = "Специализации, при которых включается этот скин. Выберите несколько или «Любая специализация»."
L["The spell that puts it down. The bar follows that totem or guardian, any rank, in any slot. Empty: whatever is in the slot."] = "Заклинание, которое его ставит. Полоса следует за этим тотемом или стражем, любого ранга, в любой ячейке. Пусто: все, что есть в ячейке."
L["The spell that puts it down. The icon follows that totem or guardian, any rank, in any slot. Empty: whatever is in the slot."] = "Заклинание, которое его ставит. Значок следует за этим тотемом или стражем, любого ранга, в любой ячейке. Пусто: все, что есть в ячейке."
L["The spell that puts it down: the icon follows that totem or guardian, any rank, into whatever slot it lands."] = "Заклинание, которое его ставит: значок следует за этим тотемом или стражем, любой ранг, в какую бы ячейку он ни попал."
L["The spell that puts the totem down, any rank. Empty: this icon's spell."] = "Заклинание, которое ставит тотем, любой ранг. Пусто: заклинание этого значка."
L["The spell whose button or icon it rides: a spell ID, a link or the name of a spell you know. Enter applies it."] = "Заклинание, на чьей кнопке или значке он находится: ID заклинания, ссылка или название известного вам заклинания. Enter применяет."
L["The spell whose button or icon it rides: an ID, a link or a known spell's name. Several ranks may be listed. Enter applies."] = "Заклинание, к чьей кнопке или значку он привязан: ID, ссылка или название известного заклинания. Можно указать несколько рангов. Enter применяет."
L["The spell whose cooldown it shows. Empty: the art's spell."] = "Заклинание, чье восстановление он показывает. Пусто: заклинание рисунка."
L["The spell whose icon it wears. A spell ID, a link, or the name of a spell you know."] = "Заклинание, чей значок он носит. ID заклинания, ссылка или название известного вам заклинания."
L["The spell whose icon it wears; Appearance > Icon > Art > Custom icon wins over it. A spell ID, a link, or the name of a spell you know."] = "Заклинание, значок которого он носит; «Внешний вид» > «Значок» > «Рисунок» > «Свой значок» главнее. ID заклинания, ссылка или название известного вам заклинания."
L["The spell whose range picks the band: a melee ability for Melee, a ranged spell for Caster. Empty: your class's usual one."] = "Заклинание, дальность которого выбирает диапазон: способность ближнего боя для режима «Ближний бой», дальнее заклинание для режима «Заклинатель». Пусто: обычное для вашего класса."
L["The spell whose range to your target decides the dim: an ID or a known spell's name. Empty: your class's usual one."] = "Заклинание, дальность которого до вашей цели определяет приглушение: ID или название известного заклинания. Пусто: обычное для вашего класса."
L["The spell whose range to your target decides the rule: an ID or a known spell's name. Any rank works."] = "Заклинание, дальность которого до вашей цели определяет правило: ID или название известного заклинания. Подходит любой ранг."
L["The spell's icon"] = "Значок заклинания"
L["The spell's name or ID."] = "Название или ID заклинания."
L["The spells it watches (any spell but these: the ones it skips), comma separated: IDs, links or names. Any rank."] = "Заклинания, за которыми он следит (любое, кроме этих: те, которые он пропускает), через запятую: ID, ссылки или названия. Любой ранг."
L["The spells it watches, comma separated: IDs, links or names. Any rank."] = "Отслеживаемые заклинания через запятую: ID, ссылки или названия. Любой ранг."
L["The spot on your screen the layout keeps its distance from when the resolution or UI scale changes."] = "Место на экране, от которого макет держит расстояние при смене разрешения или масштаба интерфейса."
L["The stack count"] = "Число стаков"
L["The stack count that fills it. 0 = the aura's most, or the custom item's Max stacks."] = "Число стаков, при котором он заполнен. 0 = максимум ауры или «Максимум стаков» своего элемента."
L["The stacks"] = "Стаки"
L["The stacks climb to Max stacks, then clear: the fill and the count."] = "Стаки растут до максимума, затем сбрасываются: заполнение и число."
L["The stacks climb to the maximum and drop: stack colours, the max colour and the count."] = "Стаки растут до максимума и падают: цвета стаков, цвет максимума и число."
L["The stacks, then the timer in brackets: 3 (7.2)."] = "Стаки, затем таймер в скобках: 3 (7.2)."
L["The stance or form you are in, or one lit while you are in it."] = "Стойка или облик, в котором вы находитесь, либо один, горящий, пока вы в нем."
L["The stance's spell ID: one this character does not have, such as another class's."] = "ID заклинания стойки: той, которой у этого персонажа нет, например другого класса."
L["The state that lights it: an aura up or missing, or a spell Ready, Recharging (a charge used) or On cooldown (none left)."] = "Состояние, которое его зажигает: аура действует или отсутствует либо заклинание «Готово», «Перезарядка» (заряд использован) или «На восстановлении» (зарядов не осталось)."
L["The swipe keeps its own opacity while Active opacity dims the icon, so only the art fades."] = "Затемнение сохраняет свою непрозрачность, пока «Активная непрозрачность» тускнит значок, поэтому блекнет только рисунок."
L["The text"] = "Текст"
L["The text to speak is set on each trigger."] = "Текст для произнесения задается в каждом триггере."
L["The text with a sample value, in its font, colour and box."] = "Текст с примерным значением, его шрифтом, цветом и рамкой."
L["The texture"] = "Текстура"
L["The time left"] = "Оставшееся время"
L["The time left on a weapon's enchant, with its charges."] = "Оставшееся время чар оружия вместе с зарядами."
L["The time left on one of your totems or guardians, by the spell that puts it down or by its slot."] = "Оставшееся время одного из ваших тотемов или стражей: по заклинанию, которое его ставит, или по ячейке."
L["The timer"] = "Таймер"
L["The timer is not running"] = "Таймер не идет"
L["The timer is running"] = "Таймер идет"
L["The timer runs"] = "Таймер идет"
L["The timer runs or it has stacks"] = "Таймер идет или есть стаки"
L["The timer runs or stacks are above 0"] = "Таймер идет или стаков больше 0"
L["The timer runs out, rests, and starts again."] = "Таймер истекает, ждет и запускается снова."
L["The top look wins when several hold."] = "Если подходит несколько, побеждает верхний вид."
L["The totem bar button this icon follows."] = "Кнопка панели тотемов, за которой следует этот значок."
L["The totem or guardian slot to watch. The icon lights while anything is in it."] = "Ячейка тотема или стража для отслеживания. Значок горит, пока в ней что-то есть."
L["The totem or guardian slot to watch. The icon lights while anything is in it. A shaman's slots hold: %s."] = "Ячейка тотема или стража для отслеживания. Значок горит, пока в ней что-то есть. Ячейки шамана содержат: %s."
L["The tracked cooldown spell."] = "Отслеживаемое заклинание с восстановлением."
L["The tracked item, or several: the icon shows the first one you carry and can use. Retargeting keeps every setting and position."] = "Отслеживаемый предмет или несколько: значок показывает первый из тех, что при вас и пригодны к использованию. Смена цели сохраняет все настройки и позицию."
L["The tracked spell. Retargeting re-keys the driver and keeps every setting and position."] = "Отслеживаемое заклинание. Смена цели пересоздает драйвер и сохраняет все настройки и позицию."
L["The tracker's readout when you point at the icon. On also turns the icon's click-through off."] = "Показания трекера при наведении на значок. Вкл. также отключает сквозные щелчки значка."
L["The unit's name"] = "Имя юнита"
L["The value counts power (45 energy, 2000 mana) instead of a percent of the bar."] = "Значение считает ресурс (45 энергии, 2000 маны), а не процент от полосы."
L["The value runs from empty to full and back: threshold colours, pips and every text follow it."] = "Значение идет от пустого до полного и обратно: цвета порогов, точки и все тексты следуют за ним."
L["The wheel"] = "Колесо"
L["The wheel is full: empty a spot first."] = "Колесо заполнено: сначала освободите место."
L["The whole cooldown"] = "Все восстановление"
L["The whole picture"] = "Вся картинка"
L["The window a ready check opens: your marker, a group message and macros to drag onto your bars."] = "Окно, которое открывается при проверке готовности: ваша метка, сообщение группе и макросы для перетаскивания на панели."
L["The window keeps the size for Max entries shown and stays on screen when empty, instead of growing with each ping."] = "Окно сохраняет размер для «Максимум записей» и остается на экране пустым, а не растет с каждым пингом."
L["The windup as it fills, and a faint outline of its spot while you reload."] = "Прицеливание по мере заполнения и бледный контур его места во время перезарядки."
L["Their own class and spec checks"] = "Собственные проверки класса и специализации"
L["Their own class checks"] = "Собственные проверки класса"
L["Then"] = "Затем"
L["Thick line"] = "Толстая линия"
L["Thick outline"] = "Толстый контур"
L["Thickness"] = "Толщина"
L["Thin line"] = "Тонкая линия"
L["Third"] = "Третий"
L["Third ammo threshold (at or below)"] = "Третий порог боеприпасов (не больше)"
L["Third ammo threshold color"] = "Цвет третьего порога боеприпасов"
L["Third threshold (%)"] = "Третий порог (%)"
L["Third threshold color"] = "Цвет третьего порога"
L["This %s fails its load conditions on this character (%s). You can still edit it. Click its eye to show it on screen."] = "%s: условия загрузки на этом персонаже не выполнены (%s). Править можно по-прежнему. Щелкните глаз, чтобы показать на экране."
L["This bar doesn't load on this character (%s). Click its eye to show it while you edit."] = "Эта полоса не загружается на этом персонаже (%s). Щелкните ее глаз, чтобы показать ее на время правки."
L["This bar wears as many skins as it can."] = "Эта полоса использует столько скинов, сколько возможно."
L["This bar's aura"] = "Аура этой полосы"
L["This bar's name"] = "Название этой полосы"
L["This bar's spell"] = "Заклинание этой полосы"
L["This character"] = "Этот персонаж"
L["This frame stops moving with the group and goes back to where it was."] = "Этот фрейм перестает двигаться вместе с группой и возвращается на прежнее место."
L["This group doesn't load on this character (%s). Click its eye to show it while you edit."] = "Эта группа не загружается на этом персонаже (%s). Щелкните ее глаз, чтобы показать ее на время правки."
L["This group follows the cursor or a nameplate. A frame can't keep up with it."] = "Эта группа следует за курсором или индикатором здоровья. Фрейм за ней не поспевает."
L["This group holds %d icons, and they would not fit. Move one out first."] = "В этой группе значков: %d, и они не поместятся. Сначала уберите один."
L["This group is not on screen, so the frame stays where it was."] = "Этой группы нет на экране, поэтому фрейм остается на месте."
L["This group reminds you of it already."] = "Эта группа уже напоминает о нем."
L["This group shows up to %d auras already."] = "Эта группа уже показывает до %d аур."
L["This hero tree is not the one chosen."] = "Эта ветка героя не выбрана."
L["This icon doesn't load on this character (%s). Click its eye to show it while you edit."] = "Этот значок не загружается на этом персонаже (%s). Щелкните его глаз, чтобы показать его на время правки."
L["This icon's own rules wait until Close gaps is off: set these on the Aura Group."] = "Собственные правила этого значка ждут, пока «Убирать промежутки» выключено: задайте их в «Группе аур»."
L["This is how Arc Auras speaks."] = "Так говорит Arc Auras."
L["This item itself: not offered"] = "Сам этот элемент: не предлагается"
L["This key pings the spell and casts nothing. Right-click clears it."] = "Эта клавиша пингует заклинание и ничего не применяет. Правый щелчок очищает."
L["This layout doesn't load on this character (%s). Click its eye to show it while you edit."] = "Этот макет не загружается на этом персонаже (%s). Щелкните его глаз, чтобы показать его на время правки."
