L["While it is queued without the rage or mana to pay for it, the icon takes this color: that swing lands as a plain hit."] = "Пока способность в очереди, а ярости или маны на нее не хватает, значок берет этот цвет: такой удар станет обычным."
L["While it is ready"] = "Пока готово"
L["While its charges are at a count"] = "Пока число зарядов в заданных пределах"
L["While its proc is up"] = "Пока действует его прок"
L["While its stacks are at a count"] = "Пока число стаков в заданных пределах"
L["While its timer is idle it shows this spell's cooldown, then its Ready look."] = "Пока его таймер простаивает, показывается восстановление этого заклинания, затем вид «Готово»."
L["While missing"] = "Пока отсутствует"
L["While not active"] = "Пока не активно"
L["While on cooldown"] = "Пока на восстановлении"
L["While out of range"] = "Пока вне дальности"
L["While out of stock"] = "Пока нет в запасе"
L["While procs are left"] = "Пока остались проки"
L["While procs left"] = "Пока остались проки"
L["While queued"] = "Пока в очереди"
L["While ready"] = "Пока готово"
L["While recharging"] = "Пока идет перезарядка"
L["While suggested"] = "Пока предложено"
L["While the aura is missing"] = "Пока ауры нет"
L["While the aura is up"] = "Пока аура действует"
L["While the aura is up the game shows it over the icon: its time, and gone the moment it drops. Works in combat."] = "Пока аура действует, игра показывает ее поверх значка: ее время; пропадает в тот же миг, как аура исчезает. Работает в бою."
L["While the aura is up, its border takes the game's color for its type: Magic, Curse, Disease or Poison. Others keep the border color."] = "Пока аура действует, ее рамка получает цвет игры для ее типа: Магия, Проклятие, Болезнь или Яд. У остальных остается цвет рамки."
L["While the aura is up, only once little time is left, only while the aura is missing, or always. Works in combat."] = "Пока аура действует, только когда осталось мало времени, только пока ауры нет или всегда. Работает в бою."
L["While the button is held"] = "Пока кнопка удерживается"
L["While the timer is idle at 0 stacks, the count shows this many: a pool reads full before its first use. Empty = off."] = "Пока таймер простаивает при 0 стаков, число показывает столько: запас выглядит полным до первого использования. Пусто = выкл."
L["While the timer runs"] = "Пока идет таймер"
L["While this bar is not loaded, its count stops until the next reset."] = "Пока эта полоса не загружена, ее счет стоит до следующего сброса."
L["While this icon is not loaded, its count stops until the next reset."] = "Пока этот значок не загружен, его счет стоит до следующего сброса."
L["While this page is open the window can be dragged, locked or not."] = "Пока эта страница открыта, окно можно перетаскивать, закреплено оно или нет."
L["While this window is open a dim icon marks the spot; drag its name tab to move it."] = "Пока открыто это окно, место отмечает тусклый значок; перетащите его вкладку с названием, чтобы переместить."
L["While this window is open the outline marks the spot; drag its name tab to move it."] = "Пока открыто это окно, место отмечает контур; перетащите его вкладку с названием, чтобы переместить."
L["While this window is open, a dim copy of the first reminder's icon marks where pulses land. On shows only the outline and name tab."] = "Пока открыто это окно, тусклая копия значка первого напоминания отмечает, куда ложатся пульсации. «Вкл.» показывает только контур и вкладку с названием."
L["While this window is open, drag this item's texts where they sit on screen. X and Y follow."] = "Пока это окно открыто, перетаскивайте тексты этого элемента на экране. X и Y следуют за ними."
L["While this window is open, each group shows its name on its top edge, which you drag it by. Off: a small green handle, name on hover."] = "Пока это окно открыто, каждая группа показывает название на верхнем краю, за него ее можно перетаскивать. Выкл.: маленькая зеленая ручка, название при наведении."
L["While this window is open, icons and bars carry a small Edit button that opens them here. Pick which kind shows it, or none."] = "Пока это окно открыто, на значках и полосах есть маленькая кнопка «Изменить», открывающая их здесь. Выберите, у каких она показывается, или ни у каких."
L["While this window is open, items that fail their load conditions are drawn anyway, so you can place and style them."] = "Пока это окно открыто, элементы, не прошедшие условия загрузки, все равно отображаются, чтобы вы могли размещать и оформлять их."
L["While this window is open, the group you edit shows edge arrows: green adds a row or column on that side, red removes one."] = "Пока это окно открыто, у редактируемой группы показаны стрелки по краям: зеленая добавляет ряд или столбец с этой стороны, красная убирает."
L["While toggled on"] = "Пока включено"
L["Who carries the aura. Buffs match on friends and you, debuffs on enemies."] = "Кто несет ауру. Положительные эффекты ищутся у союзников и вас, отрицательные - у противников."
L["Who carries the aura: a buff on you, a debuff on your target, or another unit."] = "Кто несет ауру: положительный эффект на вас, отрицательный на вашей цели или другой юнит."
L["Who carries the aura: buffs on you, your pet, party and friends, debuffs on enemies. The game hides the opposite from addons."] = "На ком аура: положительные эффекты - на вас, вашем питомце, в группе и у союзников, отрицательные - на противниках. Противоположное игра скрывает от аддонов."
L["Who carries the aura: you for a buff, your target for a debuff. You, then your target: you first. Other combinations stay dark."] = "На ком аура: вы для положительного эффекта, ваша цель для отрицательного. Вы, затем цель: сначала вы. Другие сочетания остаются темными."
L["Whole shards only"] = "Только целые осколки"
L["Whose aura"] = "Чья аура"
L["Whose casts"] = "Чьи применения"
L["Wide (3:2)"] = "Широкий (3:2)"
L["Width"] = "Ширина"
L["Width (0 = auto)"] = "Ширина (0 = авто)"
L["Windfury Totem"] = "Тотем неистовства ветра"
L["Windfury Weapon"] = "Оружие неистовства ветра"
L["Window layer"] = "Слой окна"
L["Windup"] = "Прицеливание"
L["Windup color"] = "Цвет прицеливания"
L["Wing Clip for melee, then Auto Shot with the 10 and 20 yard checks."] = "«Подрезать крылья» для ближнего боя, затем «Автоматическая стрельба» с проверками на 10 и 20 ярдов."
L["Wing Clip for melee, then Auto Shot with the 20 yard check."] = "«Подрезать крылья» для ближнего боя, затем «Автоматическая стрельба» с проверкой на 20 ярдов."
L["Wins over the rows below it."] = "Главнее строк ниже."
L["With"] = "При остатке"
L["With "] = "С "
L["With %s"] = "С %s"
L["With %s left. Click to change it."] = "При остатке %s. Щелкните, чтобы изменить."
L["With Close gaps on, set these on the Aura Group."] = "Если «Убирать промежутки» включено, задайте это в «Группе аур»."
L["With Close gaps on, the game places the row: these apply only while this window is open."] = "Если «Убирать промежутки» включено, ряд размещает игра: это действует, только пока открыто это окно."
L["With a two-hander, a shield or nothing in this hand, the icon doesn't load. It comes back when you equip a weapon there."] = "С двуручным оружием, щитом или без ничего в этой руке значок не загружается. Он вернется, когда вы наденете там оружие."
L["With both aura types, or on nameplates, it shows as Colors and badges."] = "При обоих типах аур или на индикаторах здоровья показывается как «Цвета и бейджи»."
L["With both, the hide list applies to the buffs only."] = "При обоих список скрытия действует только на положительные эффекты."
L["With both, the hide list applies to the debuffs only."] = "При обоих список скрытия действует только на отрицательные эффекты."
L["With more than one row and column, a returning icon always takes its spot back."] = "При нескольких рядах и столбцах возвращающийся значок всегда занимает свое место."
L["With no charges"] = "Без зарядов"
L["With or without a talent"] = "С талантом или без него"
L["With several out at once: the First, the Second... Counted by picks how they are counted."] = "Когда их несколько: первый, второй... «Порядок счета» задает, как их считать."
