L["WoW Forever: follows the rank you currently know, by name, so a new rank needs no new ID. Off: tracks the exact ID above."] = "WoW Forever: следует за известным вам рангом по названию, поэтому новому рангу не нужен новый ID. Выкл.: отслеживает точный ID выше."
L["WoW's own option: a short tick when a spoken line ends."] = "Собственный параметр WoW: короткий сигнал, когда произносимая строка заканчивается."
L["WoW's own text to speech volume, so it also sets chat narration."] = "Собственная громкость озвучивания текста в WoW, поэтому она влияет и на озвучивание чата."
