L["Words after the value. Not on a countdown the game draws (a spell's time left, an aura's)."] = "Слова после значения. Не для отсчета, который рисует игра (оставшееся время заклинания или ауры)."
L["Words before the value. Not on a countdown the game draws (a spell's time left, an aura's)."] = "Слова перед значением. Не для отсчета, который рисует игра (оставшееся время заклинания или ауры)."
