L["Your Cooldown Manager layout is ready. Turn off the game's own Cooldown Manager now?\n\nSettings > Cooldown Manager turns it back on."] = "Ваш макет Трекера восстановления готов. Выключить собственный Трекер восстановления игры сейчас?\n\nВключить его снова можно в «Параметры» > «Трекер восстановления»."
