L["Your Cooldown Manager's bars as groups: same spells, sizes and places. Then hide its bars in Edit Mode."] = "Полосы вашего Трекера восстановления как группы: те же заклинания, размеры и места. Затем скройте его полосы в режиме редактирования."
L["Your Marker"] = "Ваша метка"
