L["Your current stance: the stance, form or aura you are in, greyed while in none. One stance: that one, lit while you are in it."] = "Ваша текущая стойка: стойка, облик или аура, в которой вы находитесь, серая, пока ни в одной нет. «Одна стойка»: именно она, горит, пока вы в ней."
