L["Your fire trap, Immolation or Explosive: 60 seconds from laying it, then its burn on your target, its cooldown and Ready."] = "Ваша огненная ловушка, «Обжигающая» или «Взрывная»: 60 секунд с момента установки, затем ее горение на вашей цели, ее восстановление и «Готово»."
L["Your focus"] = "Ваша запомненная цель"
L["Your frost trap, Freezing or Ice: 60 seconds from laying it, then its effect on your target, its cooldown and Ready."] = "Ваша ледяная ловушка, «Замораживающая» или «Ледяная»: 60 секунд с момента установки, затем ее эффект на вашей цели, ее восстановление и «Готово»."
L["Your gear's item level, as each game reports it. After the name reads Name (34); under the name adds an Item Level line."] = "Уровень предметов вашей экипировки, как его сообщает каждая версия игры. «После названия» дает Название (34); «Под названием» добавляет строку «Уровень предмета»."
